    #[expect(clippy::too_many_arguments)]
    fn view_sidebar_conversation_row(
        dark_mode: bool,
        topic: TopicId,
        name: String,
        preview: String,
        preview_sender: String,
        unread: u64,
        selected_topic: Rc<Cell<Option<TopicId>>>,
        last_seen_at_unix_ms: u64,
        online: bool,
        avatar: SidebarAvatarHandle,
        delete_confirm_topic: Option<TopicId>,
        is_group: bool,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row};
        use iced::{Alignment, Background, Border, Length};

        // ── Avatar (shared Avatar component, 36px) ─────────────────
        let avatar_element: iced::Element<'static, AppMessage> = {
            let sidebar_avatar = avatar; // SidebarAvatarHandle
            let mut avatar = Avatar::new(name.clone())
                .size(crate::design_tokens::AVATAR_SM)
                .dark_mode(dark_mode);
            if !is_group {
                if let Some(handle) = sidebar_avatar.handle.clone() {
                    avatar = avatar.image(handle);
                }
                avatar = avatar.online_dot(online);
            }
            avatar.build()
        };

        // ── Timestamp (relative) ──────────────────────────────────
        let time_label_str = if last_seen_at_unix_ms > 0 {
            format_last_seen(Some(last_seen_at_unix_ms))
        } else {
            String::new()
        };

        // ── Preview text (single line, truncated) ──────────────────
        let preview_text = if preview.is_empty() {
            String::new()
        } else if is_group && !preview_sender.is_empty() {
            format!("{}: {}", preview_sender, format_preview(&preview))
        } else {
            format_preview(&preview)
        };

        // ── Name color and preview color: brighter/bolder if selected or unread ──
        let name_color_value = selected_topic.clone();
        let name_color = move |theme: &iced::Theme| -> Color {
            let is_selected = name_color_value.get() == Some(topic);
            if is_selected || unread > 0 {
                crate::design_tokens::text_primary(theme)
            } else {
                crate::design_tokens::text_secondary(theme)
            }
        };
        let preview_color_value = selected_topic.clone();
        let preview_color = move |_theme: &iced::Theme| -> Color {
            if preview_color_value.get() == Some(topic) {
                crate::design_tokens::text_secondary(_theme)
            } else {
                crate::design_tokens::text_muted(_theme)
            }
        };
        let time_color_value = selected_topic.clone();
        let time_color = move |_theme: &iced::Theme| -> Color {
            if time_color_value.get() == Some(topic) {
                crate::design_tokens::text_secondary(_theme)
            } else {
                crate::design_tokens::text_muted(_theme)
            }
        };

        // ── Preview row with optional unread badge ─────────────────
        let mut preview_row = Row::new()
            .push(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SupportingText,
                    preview_text.clone(),
                )
                .wrapping(iced::widget::text::Wrapping::None)
                .style(move |t| iced::widget::text::Style {
                    color: Some(preview_color(t)),
                })
                .width(Length::Fill),
            )
            .spacing(SPACE_6)
            .align_y(Alignment::Center);
        if unread > 0 {
            let count_str = if unread > 99 {
                "99+".to_string()
            } else {
                unread.to_string()
            };
            // ── Circular count badge (centered) ───────────────────
            preview_row = preview_row.push(
                container(
                    crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, count_str)
                        .color(Color::WHITE)
                        .width(Length::Shrink)
                        .height(Length::Shrink),
                )
                .center_x(Length::Fill)
                .center_y(Length::Fill)
                .width(20.0)
                .height(20.0)
                .style(move |t| container::Style {
                    background: Some(Background::Color(color_error(t))),
                    border: Border {
                        radius: 10.0.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                }),
            );
        }

        // ── Build the content row ─────────────────────────────────
        // ── Delete button ────────────────
        let is_deleting = delete_confirm_topic == Some(topic);
        let delete_btn = button(
            container(if is_deleting {
                iced::Element::<'_, AppMessage>::from(crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Delete?",
                ))
            } else {
                iced::Element::<'_, AppMessage>::from(icon_svg(ICON_CLOSE, TYPO_XS))
            })
            .center_x(Length::Fill)
            .center_y(Length::Fill)
            .width(Length::Fixed(24.0))
            .height(Length::Fixed(24.0)),
        )
        .on_press(if is_deleting {
            AppMessage::ConfirmDeleteRoom(topic)
        } else {
            AppMessage::DeleteRoomRequested(topic)
        })
        .padding(SPACE_2)
        .style(move |t, status| {
            if is_deleting {
                iced::widget::button::Style {
                    background: Some(Background::Color(color_error(t))),
                    text_color: Color::WHITE,
                    border: Border {
                        radius: SPACE_4.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                }
            } else if matches!(status, iced::widget::button::Status::Hovered) {
                iced::widget::button::Style {
                    background: Some(Background::Color(Color::from_rgba(0.8, 0.2, 0.2, 0.15))),
                    text_color: color_error(t),
                    border: Border {
                        radius: SPACE_4.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                }
            } else {
                // Invisible by default — appears only on hover (hover/overflow menu pattern)
                iced::widget::button::Style {
                    text_color: Color::from_rgba(0.0, 0.0, 0.0, 0.0),
                    background: None,
                    border: Border {
                        radius: SPACE_4.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                }
            }
        });

        // ── Name line: clip long names, show a tooltip with the full name ──
        // `Wrapping::None` keeps the row single-line; without it the text
        // wraps inside the clip container and the row grows (UI-18 finding).
        let name_label = container(
            // FONTS-06: conversation/contact name in IBM Plex Sans Medium.
            sidebar_name_text(name.clone())
                .wrapping(iced::widget::text::Wrapping::None)
                .width(Length::Fill)
                .style(move |t| iced::widget::text::Style {
                    color: Some(name_color(t)),
                }),
        )
        .width(Length::Fill)
        .clip(true);
        let name_element: iced::Element<'static, AppMessage> = if name.chars().count() > 24 {
            iced::widget::tooltip::Tooltip::new(
                name_label,
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::Metadata,
                    name.clone(),
                )
                .color(crate::design_tokens::text_primary(&Self::theme_from_dark(
                    dark_mode,
                ))),
                iced::widget::tooltip::Position::Right,
            )
            .into()
        } else {
            name_label.into()
        };

        let content_row = Row::new()
            .push(avatar_element)
            .push(
                Column::new()
                    .push(
                        Row::new()
                            .push(name_element)
                            .push(
                                crate::fonts::type_role_text(
                                    crate::fonts::TypeRole::Metadata,
                                    time_label_str.clone(),
                                )
                                .style(move |t| iced::widget::text::Style {
                                    color: Some(time_color(t)),
                                }),
                            )
                            .spacing(SPACE_4)
                            .align_y(Alignment::Center),
                    )
                    .push(preview_row)
                    .spacing(SPACE_2)
                    .width(Length::Fill),
            )
            .push(delete_btn)
            .spacing(SPACE_8)
            .padding([SPACE_6, SPACE_12])
            .width(Length::Fill);

        // ── Clickable button wrapper ──────────────────────────────
        let selected_for_btn = selected_topic.clone();
        let btn = button(content_row)
            .on_press(AppMessage::SelectConversation(topic))
            .width(Length::Fill)
            .padding(0)
            .style(move |t, status| {
                let is_selected = selected_for_btn.get() == Some(topic);
                let bg = if is_selected {
                    Some(Background::Color(crate::design_tokens::surface_selected(t)))
                } else if matches!(status, iced::widget::button::Status::Hovered) {
                    Some(Background::Color(crate::design_tokens::surface_hover(t)))
                } else {
                    None
                };
                iced::widget::button::Style {
                    background: bg,
                    border: iced::Border {
                        // A thin primary border keeps the selected row visible
                        // for keyboard focus (Tab / arrow navigation).
                        color: if is_selected {
                            crate::design_tokens::primary(t)
                        } else {
                            iced::Color::TRANSPARENT
                        },
                        width: if is_selected { 1.0 } else { 0.0 },
                        radius: crate::design_tokens::RADIUS_MD.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                }
            });

        let selected_for_unread = selected_topic.clone();
        container(btn)
            .width(Length::Fill)
            .style(move |t| {
                let is_selected = selected_for_unread.get() == Some(topic);
                if unread > 0 && !is_selected {
                    let primary = crate::design_tokens::primary(t);
                    container::Style {
                        background: Some(Background::Color(Color::from_rgba(
                            primary.r, primary.g, primary.b, 0.07,
                        ))),
                        border: Border::default(),
                        ..Default::default()
                    }
                } else {
                    container::Style {
                        ..Default::default()
                    }
                }
            })
            .into()
    }

    fn sidebar_discovered_peers_dependency(&self) -> SidebarDiscoveredPeersDependency {
        // Return cached dependency if revision hasn't changed.
        let cur_revision = self.discovered_sidebar_revision;
        if self.cached_discovered_revision.get() == cur_revision {
            if let Some(ref dep) = *self.cached_discovered_dep.borrow() {
                return dep.clone();
            }
        }

        let mut peers: Vec<SidebarDiscoveredPeerRow> = self
            .discovered_peers
            .iter()
            .filter_map(|peer| {
                let fid = boru_core::friends::FriendId::from_public_key(*peer);
                // Skip peers who are already friends — show only non-friend peers.
                let is_friend = self
                    .friends
                    .get(&fid)
                    .map(|r| r.relationship.can_message())
                    .unwrap_or(false);
                if is_friend {
                    return None;
                }
                Some(SidebarDiscoveredPeerRow {
                    peer: *peer,
                    display_name: self.resolve_name(peer),
                    avatar: Self::sidebar_avatar_handle(
                        self.friend_image_handles
                            .get(peer)
                            .and_then(|avatar| avatar.as_ref()),
                    ),
                    online: self.neighbors.contains(peer),
                    is_friend: false,
                    request_state: self.outgoing_request_states.get(peer).cloned(),
                    profile_version: self.friend_profile_versions.get(peer).copied().unwrap_or(0),
                })
            })
            .collect();
        peers.sort_by(|a, b| a.display_name.cmp(&b.display_name));
        let dep = SidebarDiscoveredPeersDependency {
            dark_mode: self.dark_mode,
            peers,
        };
        self.cached_discovered_revision.set(cur_revision);
        *self.cached_discovered_dep.borrow_mut() = Some(dep.clone());
        dep
    }

    /// "Discovered Peers" section of the sidebar - gossip-connected peers.
    fn view_sidebar_discovered_peers(&self) -> iced::Element<'_, AppMessage> {
        iced::widget::lazy(
            self.sidebar_discovered_peers_dependency(),
            Self::view_sidebar_discovered_peers_content,
        )
        .into()
    }

    fn view_sidebar_discovered_peers_content(
        dep: &SidebarDiscoveredPeersDependency,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row};
        use iced::{Alignment, Length};

        let mut section = Column::new().spacing(SPACE_2);

        let theme = Self::theme_from_dark(dep.dark_mode);
        let has_peers = !dep.peers.is_empty();
        for peer in &dep.peers {
            // Avatar with online dot.
            let mut avatar = Avatar::new(peer.display_name.clone())
                .size(crate::design_tokens::AVATAR_SM)
                .dark_mode(dep.dark_mode)
                .online_dot(peer.online);
            if let Some(handle) = peer.avatar.handle.clone() {
                avatar = avatar.image(handle);
            }

            // Label line: clip long display names and show the full text in a tooltip.
            let label_text = sidebar_name_text(peer.display_name.clone())
                .color(crate::design_tokens::text_primary(&theme))
                .width(Length::Fill);
            let label_el: iced::Element<'static, AppMessage> =
                if peer.display_name.chars().count() > 24 {
                    iced::widget::tooltip::Tooltip::new(
                        container(label_text).width(Length::Fill).clip(true),
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Metadata,
                            peer.display_name.clone(),
                        )
                        .color(crate::design_tokens::text_primary(&theme)),
                        iced::widget::tooltip::Position::Right,
                    )
                    .into()
                } else {
                    container(label_text).width(Length::Fill).clip(true).into()
                };

            let mut row_el = Row::new()
                .push(avatar.build())
                .push(label_el)
                .spacing(SPACE_8)
                .align_y(Alignment::Center)
                .padding([SPACE_4, SPACE_8])
                .width(Length::Fill);

            // Chat button for every discovered peer (friend features disabled)
            row_el = row_el.push(
                button(crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Chat",
                ))
                .on_press(AppMessage::OpenFriendChat(peer.peer))
                    .style(crate::ui_components::button_secondary_style)
                    .padding([SPACE_4, SPACE_10]),
            );

            // Browse Files button for every discovered peer
            row_el = row_el.push(
                button(crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Browse Files",
                ))
                .on_press(AppMessage::BrowsePeerCatalogue(peer.peer))
                    .style(crate::ui_components::button_secondary_style)
                    .padding([SPACE_4, SPACE_10]),
            );

            section = section.push(container(row_el).width(Length::Fill));
        }

        if !has_peers {
            section = section.push(sidebar_empty_state(
                Icon::Search,
                "No peers discovered yet",
                "Peers on your local network will appear here.",
                None,
            ));
        }

        section.into()
    }

    /// Cached dependency for the sidebar's Public Rooms section.
    fn sidebar_public_rooms_dependency(&self) -> SidebarPublicRoomsDependency {
        // Return cached dependency if revision hasn't changed — avoids the
        // directory_store lock on every render when public rooms haven't changed.
        let cur_revision = self.public_rooms_sidebar_revision;
        if self.cached_public_rooms_revision.get() == cur_revision {
            if let Some(ref dep) = *self.cached_public_rooms_dep.borrow() {
                return dep.clone();
            }
        }

        let rooms: Vec<SidebarPublicRoomRow> = {
            let store = self.directory_store.lock().unwrap();
            let mut list = store.list_active();
            // Sort by member count descending, then by room name.
            list.sort_by(|(a, _), (b, _)| {
                b.member_count
                    .cmp(&a.member_count)
                    .then_with(|| a.room_name.cmp(&b.room_name))
            });
            list.into_iter()
                .map(|(ad, author)| SidebarPublicRoomRow {
                    room_name: ad.room_name.clone(),
                    member_count: ad.member_count,
                    author,
                    advertisement: ad,
                })
                .collect()
        };
        let dep = SidebarPublicRoomsDependency {
            dark_mode: self.dark_mode,
            local_public: self.local_public,
            rooms,
        };
        self.cached_public_rooms_revision.set(cur_revision);
        *self.cached_public_rooms_dep.borrow_mut() = Some(dep.clone());
        dep
    }

    /// \"Public Rooms\" section of the sidebar — rooms advertised on the directory topic.
    fn view_sidebar_public_rooms(&self) -> iced::Element<'_, AppMessage> {
        iced::widget::lazy(
            self.sidebar_public_rooms_dependency(),
            Self::view_sidebar_public_rooms_content,
        )
        .into()
    }

    fn view_sidebar_public_rooms_content(
        dep: &SidebarPublicRoomsDependency,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row};
        use iced::{Alignment, Length};

        let mut section = Column::new().spacing(SPACE_2);

        for room in &dep.rooms {
            let room_name = room.room_name.clone();
            let member_info = if room.member_count > 0 {
                format!("{} members", room.member_count)
            } else {
                String::new()
            };
            let ad_for_join = room.advertisement.clone();
            let is_local_room = room.author == dep.local_public;
            let mut actions = Row::new().push(
                button(crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Join",
                ))
                .on_press(AppMessage::DirectoryRoomJoin(ad_for_join))
                .style(crate::ui_components::button_secondary_style)
                .padding([SPACE_4, SPACE_8]),
            );
            if is_local_room {
                actions = actions.push(
                    button(crate::fonts::type_role_text(
                        crate::fonts::TypeRole::ButtonLabel,
                        "Delete",
                    ))
                    .on_press(AppMessage::DeleteDirectoryRoom(room.advertisement.topic))
                        .style(crate::ui_components::button_secondary_style)
                        .padding([SPACE_4, SPACE_8]),
                );
            }

            // Room name line: clip long names and show the full text in a tooltip.
            let name_text = sidebar_name_text(room_name.clone())
                .color(crate::design_tokens::text_primary(&Self::theme_from_dark(
                    dep.dark_mode,
                )))
                .width(Length::Fill);
            let name_el: iced::Element<'static, AppMessage> = if room_name.chars().count() > 24 {
                iced::widget::tooltip::Tooltip::new(
                    container(name_text).width(Length::Fill).clip(true),
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::Metadata,
                        room_name.clone(),
                    )
                    .color(crate::design_tokens::text_primary(&Self::theme_from_dark(
                        dep.dark_mode,
                    ))),
                    iced::widget::tooltip::Position::Right,
                )
                .into()
            } else {
                container(name_text).width(Length::Fill).clip(true).into()
            };

            let row_el = Row::new()
                .push(
                    Column::new()
                        .push(name_el)
                        .push(
                            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, member_info)
                                .style(text_muted_style),
                        )
                        .spacing(SPACE_2)
                        .width(Length::Fill),
                )
                .push(actions)
                .spacing(SPACE_4)
                .align_y(Alignment::Center)
                .padding([SPACE_4, SPACE_12])
                .width(Length::Fill);

            section = section.push(container(row_el).width(Length::Fill));
        }

        if dep.rooms.is_empty() {
            section = section.push(sidebar_empty_state(
                Icon::Chat,
                "No public rooms discovered yet",
                "Rooms advertised on the directory will appear here.",
                None,
            ));
        }

        section.into()
    }

    /// Old small avatar block (pre-UI-06).  Superseded by the shared
    /// `ui_components::Avatar`; kept only until UI-22 cleanup.
    #[expect(dead_code)]
    fn peer_avatar_block(
        avatar: SidebarAvatarHandle,
        peer: PublicKey,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{container};
        use iced::{Background, Border, Length};

        if let Some(handle) = avatar.handle {
            return iced::widget::image(handle)
                .width(Length::Fixed(24.0))
                .height(Length::Fixed(24.0))
                .into();
        }

        let bytes = peer.as_bytes();
        let r = bytes[0] as f32 / 255.0;
        let g = bytes[1] as f32 / 255.0;
        let b = bytes[2] as f32 / 255.0;
        let avatar_color = Color::from_rgb(r, g, b);

        let short = peer.fmt_short().to_string();
        let first_char = short.chars().next().unwrap_or('?').to_string();

        container(
            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, first_char)
                .color(Color::WHITE)
                .width(Length::Fill),
        )
        .center_y(Length::Fill)
        .width(Length::Fixed(24.0))
        .height(Length::Fixed(24.0))
        .style(move |_t| container::Style {
            background: Some(Background::Color(avatar_color)),
            border: Border {
                radius: 12.0.into(),
                ..Default::default()
            },
            ..Default::default()
        })
        .into()
    }

    fn sidebar_friends_dependency(&self) -> SidebarFriendsDependency {
        SidebarFriendsDependency {
            dark_mode: self.dark_mode,
            sidebar_revision: self.friends_sidebar_revision,
            friend_request_search_input: self.friend_request_search_input.clone(),
            friend_request_error: self.friend_request_error.clone(),
        }
    }

    /// "Friends" section of the sidebar — all friends with "Message" button.
    fn view_sidebar_friends(&self) -> iced::Element<'_, AppMessage> {
        let rows_dep = self.sidebar_friends_rows_dependency();
        iced::widget::lazy(self.sidebar_friends_dependency(), move |dep| {
            Self::view_sidebar_friends_content(dep, rows_dep.clone())
        })
        .into()
    }

    fn sidebar_friends_rows_dependency(&self) -> SidebarFriendsRowsDependency {
        // Return cached dependency if revision hasn't changed.
        let cur_revision = self.friends_sidebar_revision;
        if self.cached_friends_rows_revision.get() == cur_revision {
            if let Some(ref dep) = *self.cached_friends_rows_dep.borrow() {
                return dep.clone();
            }
        }

        let mut friends: Vec<SidebarFriendRow> = self
            .friends
            .iter()
            .filter_map(|(fid, record)| {
                if !record.relationship.can_message() {
                    return None;
                }
                let peer = fid.parse_public_key().ok()?;
                Some(SidebarFriendRow {
                    peer,
                    label: record.display_label(fid, &peer),
                    avatar: Self::sidebar_avatar_handle(
                        self.friend_image_handles
                            .get(&peer)
                            .and_then(|avatar| avatar.as_ref()),
                    ),
                    presence: self.peer_presence(&peer),
                    profile_version: self
                        .friend_profile_versions
                        .get(&peer)
                        .copied()
                        .unwrap_or(0),
                })
            })
            .collect();
        friends.sort_by(|a, b| a.label.cmp(&b.label));
        let dep = SidebarFriendsRowsDependency {
            dark_mode: self.dark_mode,
            sidebar_revision: self.friends_sidebar_revision,
            friends,
        };
        self.cached_friends_rows_revision.set(cur_revision);
        *self.cached_friends_rows_dep.borrow_mut() = Some(dep.clone());
        dep
    }

    fn view_sidebar_friends_content(
        dep: &SidebarFriendsDependency,
        rows_dep: SidebarFriendsRowsDependency,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row, Space};
        use iced::{Alignment, Length};

        let mut section = Column::new().spacing(SPACE_2);

        // Add-friend field: shared text input + trailing add-person icon.
        // Submission (Enter), validation (error border) and focus behaviour
        // are preserved: Enter submits the current value, the trailing icon
        // button submits the same message, and the field shows an error state
        // when a previous submission failed.
        let add_input = text_input_field(
            "Add friend by key…",
            &dep.friend_request_search_input,
            AppMessage::FriendRequestSearchChanged,
            !dep.friend_request_error.is_empty(),
        );
        let add_btn = button(
            Icon::UserPlus
                .build()
                .size(IconSize::Sm)
                .interactive(true)
                .build(),
        )
        .on_press(AppMessage::FriendRequestSend(
            dep.friend_request_search_input.clone(),
        ))
        .padding([SPACE_6, SPACE_8])
        .style(crate::ui_components::button_secondary_style);

        section = section.push(
            container(
                Row::new()
                    .push(add_input)
                    .push(
                        Space::new()
                            .width(Length::Fixed(SPACE_4))
                            .height(Length::Shrink),
                    )
                    .push(add_btn)
                    .align_y(Alignment::Center),
            )
            .padding(iced::Padding {
                top: SPACE_2,
                right: SPACE_12,
                bottom: SPACE_4,
                left: SPACE_12,
            })
            .width(Length::Fill),
        );

        let rows = iced::widget::lazy(rows_dep, Self::view_sidebar_friends_rows_content);

        section = section.push(rows);

        section.into()
    }

    fn view_sidebar_friends_rows_content(
        dep: &SidebarFriendsRowsDependency,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row};
        use iced::{Alignment, Length};

        let _timer = PerfTracker::timer("view_sidebar_friends_rows", "build");
        let theme = Self::theme_from_dark(dep.dark_mode);
        let mut section = Column::new().spacing(SPACE_2);

        let has_friends = !dep.friends.is_empty();
        for friend in &dep.friends {
            let online = friend.presence != PeerPresence::Offline;

            // Avatar with online status dot.
            let mut avatar = Avatar::new(friend.label.clone())
                .size(crate::design_tokens::AVATAR_SM)
                .dark_mode(dep.dark_mode)
                .online_dot(online);
            if let Some(handle) = friend.avatar.handle.clone() {
                avatar = avatar.image(handle);
            }

            // Label line: clip long friend labels / peer IDs and show the
            // full text in a tooltip.
            let label_text = sidebar_name_text(friend.label.clone())
                .color(if online {
                    crate::design_tokens::text_primary(&theme)
                } else {
                    crate::design_tokens::text_secondary(&theme)
                })
                .width(Length::Fill);
            let label_el: iced::Element<'static, AppMessage> = if friend.label.chars().count() > 24
            {
                iced::widget::tooltip::Tooltip::new(
                    container(label_text).width(Length::Fill).clip(true),
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::Metadata,
                        friend.label.clone(),
                    )
                    .color(crate::design_tokens::text_primary(&theme)),
                    iced::widget::tooltip::Position::Right,
                )
                .into()
            } else {
                container(label_text).width(Length::Fill).clip(true).into()
            };

            // Overflow menu (⋮) — opens the friend profile overflow menu.
            let overflow_btn = button(
                Icon::MoreVertical
                    .build()
                    .size(IconSize::Md)
                    .interactive(true)
                    .build(),
            )
            .on_press(AppMessage::OpenFriendProfile(friend.peer))
            .padding([SPACE_4, SPACE_8])
            .style(move |t, status| iced::widget::button::Style {
                background: matches!(status, iced::widget::button::Status::Hovered)
                    .then(|| iced::Background::Color(crate::design_tokens::surface_hover(t))),
                border: iced::Border {
                    radius: crate::design_tokens::RADIUS_SM.into(),
                    ..Default::default()
                },
                text_color: if matches!(status, iced::widget::button::Status::Hovered) {
                    crate::design_tokens::primary(t)
                } else {
                    crate::design_tokens::text_muted(t)
                },
                ..Default::default()
            });

            let row_el = Row::new()
                .push(avatar.build())
                .push(label_el)
                .push(overflow_btn)
                .spacing(SPACE_8)
                .align_y(Alignment::Center)
                .padding([SPACE_4, SPACE_8])
                .width(Length::Fill);

            // Make the entire row clickable to open the friend profile
            let row_container = button(row_el)
                .on_press(AppMessage::OpenFriendProfile(friend.peer))
                .width(Length::Fill)
                .padding(0)
                .style(move |t, status| iced::widget::button::Style {
                    background: matches!(status, iced::widget::button::Status::Hovered)
                        .then(|| iced::Background::Color(crate::design_tokens::surface_hover(t))),
                    border: iced::Border {
                        radius: crate::design_tokens::RADIUS_MD.into(),
                        ..Default::default()
                    },
                    text_color: iced::Color::TRANSPARENT,
                    ..Default::default()
                });

            section = section.push(container(row_container).width(Length::Fill));
        }

        if !has_friends {
            section = section.push(sidebar_empty_state(
                Icon::Friend,
                "No friends added yet",
                "Add someone using a key or invitation.",
                Some(("Add Friend", AppMessage::OpenFriendRequests)),
            ));
        }

        section.into()
    }

    fn sidebar_requests_dependency(&self) -> SidebarRequestsDependency {
        // Return cached dependency if revision hasn't changed.
        let cur_revision = self.requests_sidebar_revision;
        if self.cached_requests_revision.get() == cur_revision {
            if let Some(ref dep) = *self.cached_requests_dep.borrow() {
                return dep.clone();
            }
        }

        let local_pk_str = self.local_public.to_string();
        let mut incoming: Vec<SidebarRequestRow> = self
            .friend_request_store
            .list_incoming_by_status(
                &local_pk_str,
                boru_core::friend_request::FriendRequestStatus::Pending,
            )
            .into_iter()
            .filter_map(|request| {
                let requester = std::str::FromStr::from_str(&request.requester).ok()?;
                Some(SidebarRequestRow {
                    request_id: request.id.clone(),
                    requester,
                    label: self.resolve_name(&requester),
                })
            })
            .collect();
        incoming.sort_by(|a, b| a.label.cmp(&b.label));

        // Fetch pending group invites
        let group_invites: Vec<SidebarGroupInviteRow> = self
            .storage
            .as_ref()
            .map(|st| {
                let now_ms = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_millis() as u64;
                st.get_pending_group_invites(&self.local_public.to_vec(), now_ms)
                    .unwrap_or_default()
                    .into_iter()
                    .map(|inv| SidebarGroupInviteRow {
                        invite_id: inv.invite_id.to_vec(),
                        inviter_public_key: inv.inviter_public_key.clone(),
                        group_name: String::new(), // group name not stored in invite row
                        ticket: inv.ticket,
                        inviter_label: {
                            let mut arr = [0u8; 32];
                            let len = inv.inviter_public_key.len().min(32);
                            arr[..len].copy_from_slice(&inv.inviter_public_key[..len]);
                            PublicKey::from_bytes(&arr)
                                .map(|pk| self.resolve_name(&pk))
                                .unwrap_or_else(|_| "Unknown".to_string())
                        },
                    })
                    .collect()
            })
            .unwrap_or_default();

        let dep = SidebarRequestsDependency {
            dark_mode: self.dark_mode,
            requests_revision: self.requests_sidebar_revision,
            incoming,
            friend_request_error: self.friend_request_error.clone(),
            group_invites,
            tunnel_requests: self
                .tunnel_requests
                .iter()
                .map(|request| SidebarTunnelRequestRow {
                    peer: request.peer,
                    tunnel_id: request.tunnel_id.clone(),
                    label: self.resolve_name(&request.peer),
                })
                .collect(),
        };
        self.cached_requests_revision.set(cur_revision);
        *self.cached_requests_dep.borrow_mut() = Some(dep.clone());
        dep
    }

    /// "Friend Requests" section of the sidebar — incoming pending requests.
    fn view_sidebar_requests(&self) -> iced::Element<'_, AppMessage> {
        iced::widget::lazy(
            self.sidebar_requests_dependency(),
            Self::view_sidebar_requests_content,
        )
        .into()
    }

    fn view_sidebar_requests_content(
        dep: &SidebarRequestsDependency,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row};
        use iced::{Alignment, Length};

        let theme = Self::theme_from_dark(dep.dark_mode);
        let mut section = Column::new().spacing(SPACE_2);

        // Manage button for opening the full friend requests screen
        section = section.push(
            container(secondary_button(
                "Manage Requests",
                Some(AppMessage::OpenFriendRequests),
                false,
            ))
            .padding(iced::Padding {
                top: SPACE_2,
                right: SPACE_12,
                bottom: SPACE_4,
                left: SPACE_12,
            })
            .width(Length::Fill),
        );

        let has_requests = !dep.incoming.is_empty()
            || !dep.group_invites.is_empty()
            || !dep.tunnel_requests.is_empty();

        if !has_requests {
            section = section.push(sidebar_empty_state(
                Icon::Notification,
                "No pending requests",
                "New friend requests will appear here.",
                None,
            ));
        } else {
            // ── Friend requests ──
            for request in &dep.incoming {
                let row_el = Row::new()
                    .push(
                        sidebar_name_text(request.label.clone()).width(Length::Fill),
                    )
                    .push(
                        button(Icon::Check.build().size(IconSize::Xs).build())
                            .on_press(AppMessage::IncomingFriendRequestAccept {
                                request_id: request.request_id.clone(),
                                peer: request.requester,
                            })
                            .padding([SPACE_2, SPACE_4])
                            .style(move |t, _status| iced::widget::button::Style {
                                background: Some(iced::Background::Color(accent_primary(t))),
                                text_color: Color::WHITE,
                                border: iced::Border {
                                    radius: SPACE_4.into(),
                                    ..Default::default()
                                },
                                ..Default::default()
                            }),
                    )
                    .push(
                        button(Icon::Close.build().size(IconSize::Xs).build())
                            .on_press(AppMessage::IncomingFriendRequestDecline {
                                request_id: request.request_id.clone(),
                                peer: request.requester,
                            })
                            .padding([SPACE_2, SPACE_4])
                            .style(move |t, _status| iced::widget::button::Style {
                                background: Some(iced::Background::Color(color_error(t))),
                                text_color: Color::WHITE,
                                border: iced::Border {
                                    radius: SPACE_4.into(),
                                    ..Default::default()
                                },
                                ..Default::default()
                            }),
                    )
                    .spacing(SPACE_4)
                    .align_y(Alignment::Center)
                    .padding([SPACE_4, SPACE_12])
                    .width(Length::Fill);

                section = section.push(container(row_el).width(Length::Fill));
            }

            // ── Group invites ──
            if !dep.group_invites.is_empty() {
                for invite in &dep.group_invites {
                    let inviter_label = &invite.inviter_label;
                    let invite_id = invite.invite_id.clone();
                    let row_el = Row::new()
                        .push(
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Body,
                                format!("Group invite from {inviter_label}"),
                            )
                            .width(Length::Fill),
                        )
                        .push(
                            button(crate::fonts::type_role_text(
                                crate::fonts::TypeRole::ButtonLabel,
                                "Join",
                            ))
                            .on_press(AppMessage::AcceptGroupInvite(invite_id))
                                .padding([SPACE_2, SPACE_4])
                                .style(move |t, _status| iced::widget::button::Style {
                                    background: Some(iced::Background::Color(accent_primary(t))),
                                    text_color: Color::WHITE,
                                    border: iced::Border {
                                        radius: SPACE_4.into(),
                                        ..Default::default()
                                    },
                                    ..Default::default()
                                }),
                        )
                        .spacing(SPACE_4)
                        .align_y(Alignment::Center)
                        .padding([SPACE_4, SPACE_12])
                        .width(Length::Fill);

                    section = section.push(container(row_el).width(Length::Fill));
                }
            }

            // ── Tunnel requests ──
            for request in &dep.tunnel_requests {
                let row_el = Row::new()
                    .push(
                        Row::new()
                            .push(
                                sidebar_name_text(request.label.clone()).width(Length::Fill),
                            )
                            .push(
                                container(
                                    crate::fonts::type_role_text(
                                        crate::fonts::TypeRole::Metadata,
                                        "Tunnel",
                                    )
                                    .color(accent_primary(&theme)),
                                )
                                .padding([SPACE_2, SPACE_4])
                                .style(move |t| {
                                    iced::widget::container::Style {
                                        background: Some(iced::Background::Color(bg_surface(t))),
                                        border: iced::Border {
                                            color: border_muted(t),
                                            width: 1.0,
                                            radius: SPACE_4.into(),
                                        },
                                        ..Default::default()
                                    }
                                }),
                            )
                            .spacing(SPACE_4)
                            .align_y(Alignment::Center)
                            .width(Length::Fill),
                    )
                    .push(
                        button(Icon::Check.build().size(IconSize::Xs).build())
                            .on_press(AppMessage::AcceptTunnelRequest(request.tunnel_id.clone()))
                            .padding([SPACE_2, SPACE_4])
                            .style(move |t, _status| iced::widget::button::Style {
                                background: Some(iced::Background::Color(accent_primary(t))),
                                text_color: Color::WHITE,
                                border: iced::Border {
                                    radius: SPACE_4.into(),
                                    ..Default::default()
                                },
                                ..Default::default()
                            }),
                    )
                    .push(
                        button(Icon::Close.build().size(IconSize::Xs).build())
                            .on_press(AppMessage::DeclineTunnelRequest(request.tunnel_id.clone()))
                            .padding([SPACE_2, SPACE_4])
                            .style(move |t, _status| iced::widget::button::Style {
                                background: Some(iced::Background::Color(color_error(t))),
                                text_color: Color::WHITE,
                                border: iced::Border {
                                    radius: SPACE_4.into(),
                                    ..Default::default()
                                },
                                ..Default::default()
                            }),
                    )
                    .spacing(SPACE_4)
                    .align_y(Alignment::Center)
                    .padding([SPACE_4, SPACE_12])
                    .width(Length::Fill);

                section = section.push(container(row_el).width(Length::Fill));
            }
        }

        if !dep.friend_request_error.is_empty() {
            section = section.push(
                container(
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::SupportingText,
                        dep.friend_request_error.clone(),
                    )
                    .color(color_error(&theme)),
                )
                .padding([SPACE_2, SPACE_12]),
            );
        }

        section.into()
    }

    // ── Home-rail card selectors (fine-grained state slices) ─────────────
    // Each selector returns ONLY the data its card renders: the Online Peers
    // selector never reads `recent_activity` or the tunnel service, the
    // Recent Activity selector never reads friends/presence, and the Tunnels
    // selector never reads friends/activity. The matching builders run inside
    // `iced::widget::lazy`, which compares the fresh selector value with the
    // previous frame and reuses the built subtree when nothing in the slice
    // changed — so a data change in one card rebuilds exactly that card.

    /// Selector for the Online Peers card: friends with live presence plus
    /// the total friend count for the badge denominator.
    fn online_peers_card_data(&self) -> OnlinePeersCardData {
        let total_friends = self
            .friends
            .iter()
            .filter(|(_, r)| r.relationship.can_message())
            .count();
        let rows = self
            .friends
            .iter()
            .filter_map(|(fid, _)| {
                let pk = fid.parse_public_key().ok()?;
                let presence = self.peer_presence(&pk);
                if presence == PeerPresence::Offline {
                    return None;
                }
                Some(OnlinePeerRow {
                    pk,
                    name: self.resolve_name(&pk),
                    presence,
                    avatar: Self::sidebar_avatar_handle(
                        self.friend_image_handles
                            .get(&pk)
                            .and_then(|slot| slot.as_ref()),
                    ),
                })
            })
            .collect();
        OnlinePeersCardData {
            dark_mode: self.dark_mode,
            total_friends,
            rows,
            compact_header: self.home_compact_headers(),
            home_menu_item_opacity_bits: self.home_menu_item_opacity.to_bits(),
        }
    }

    /// Selector for the Recent Activity card: the ring-buffer slice only
    /// (badge total + the newest 15 rendered rows). `tick` is included so the
    /// per-second ActivityTick refreshes relative timestamps while idle.
    fn recent_activity_card_data(&self) -> RecentActivityCardData {
        let rows = self
            .recent_activity
            .iter()
            .take(15)
            .map(|event| ActivityRow {
                description: event.description.clone(),
                kind: event.kind,
                timestamp: event.timestamp,
            })
            .collect();
        RecentActivityCardData {
            dark_mode: self.dark_mode,
            tick: self.activity_tick,
            total: self.recent_activity.len(),
            rows,
            compact_header: self.home_compact_headers(),
            home_menu_item_opacity_bits: self.home_menu_item_opacity.to_bits(),
        }
    }

    /// Selector for the Tunnels card: the live TunnelService snapshot plus
    /// the shared-tunnel name map needed to label rows. `tick` is included so
    /// a tunnel expiring while idle flips to "Expired" within a second.
    fn tunnels_card_data(&self) -> TunnelsCardData {
        let rows = self
            .tunnel_service
            .list_tunnels()
            .into_iter()
            .map(|def| {
                let now = now_ms().max(0) as u64;
                let expired = def.status != TunnelStatus::Revoked && def.expires_at_ms <= now;
                let endpoint = match def.target {
                    boru_core::tunnel::service::TunnelTarget::Tcp { host, port } => {
                        tunnel_target_label(host, port)
                    }
                };
                let name = self
                    .shared_tunnels
                    .get(&def.id)
                    .map(|state| state.service_name.clone())
                    .unwrap_or_else(|| {
                        self.names
                            .get(&def.allowed_peer)
                            .cloned()
                            .unwrap_or_else(|| def.allowed_peer.fmt_short().to_string())
                    });
                TunnelRow {
                    id: def.id,
                    name,
                    endpoint,
                    status: def.status,
                    expired,
                }
            })
            .collect();
        TunnelsCardData {
            dark_mode: self.dark_mode,
            tick: self.activity_tick,
            rows,
            compact_header: self.home_compact_headers(),
            home_menu_item_opacity_bits: self.home_menu_item_opacity.to_bits(),
        }
    }

    /// True when the home content width is narrow enough that card headers
    /// switch to the two-line compact layout (UI-HOME-15).
    fn home_compact_headers(&self) -> bool {
        crate::design_tokens::home_content_width(self.window_width)
            < crate::design_tokens::HOME_COMPACT_HEADER_CONTENT
    }

    /// Build the Online Peers card subtree. Runs inside `iced::widget::lazy`,
    /// so it is only re-invoked when `OnlinePeersCardData` actually changes.
    fn view_online_peers_card(dep: &OnlinePeersCardData) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, Column, Row, Space};
        use iced::{Alignment, Length};

        let theme = Self::theme_from_dark(dep.dark_mode);
        let peer_rows: Vec<iced::Element<'static, AppMessage>> = dep
            .rows
            .iter()
            .map(|row| {
                let mut avatar = Avatar::new(row.name.clone())
                    .size(crate::design_tokens::AVATAR_SM)
                    .dark_mode(dep.dark_mode)
                    .online_dot(true)
                    .fallback_icon(Icon::Friend);
                if let Some(handle) = row.avatar.handle.clone() {
                    avatar = avatar.image(handle);
                }
                // Structured row: avatar (with live online dot) + a two-line
                // text column — display name on top, live presence secondary
                // status below (Online / Away / Connecting…, coloured with
                // the status palette).
                let presence_color = row.presence.color(&theme);
                let text_col = Column::new()
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Body,
                            row.name.clone(),
                        )
                        .color(text_system(&theme))
                        .width(Length::Fill)
                        .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                    )
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::SupportingText,
                            row.presence.label(),
                        )
                        .color(presence_color),
                    )
                    .spacing(crate::design_tokens::SPACE_2)
                    .align_x(Alignment::Start)
                    .width(Length::Fill);
                let row_el = Row::new()
                    // Zero-width spacer enforces the 60 px two-line row
                    // rhythm as a MINIMUM; a wrapped display name grows the
                    // row instead of being clipped (UI-HOME-10).
                    .push(Space::new().width(Length::Fixed(0.0)).height(Length::Fixed(crate::card_shell::PEER_ROW_HEIGHT)))
                    .push(avatar.build())
                    .push(Space::new().width(Length::Fixed(SPACE_8)))
                    .push(text_col)
                    .spacing(0)
                    .align_y(Alignment::Center);
                button(row_el)
                    .on_press(AppMessage::OpenConversation(row.pk))
                    .width(Length::Fill)
                    .padding([0.0, SPACE_8])
                    .style(|t, status| iced::widget::button::Style {
                        // Hover surface for the interactive row. Note: iced
                        // 0.14 `button::Status` has no `Focused` variant
                        // (Active/Hovered/Pressed/Disabled only) and buttons
                        // are not keyboard-focusable in this version, so
                        // hover is the interaction affordance here.
                        background: matches!(status, iced::widget::button::Status::Hovered).then(
                            || iced::Background::Color(crate::design_tokens::surface_hover(t)),
                        ),
                        border: iced::Border {
                            radius: crate::design_tokens::RADIUS_SM.into(),
                            ..Default::default()
                        },
                        text_color: iced::Color::TRANSPARENT,
                        ..Default::default()
                    })
                    .into()
            })
            .collect();

        // Content-driven body with a floor: the list grows with the number
        // of online peers up to five visible rows (the 6th scrolls) and never
        // collapses below PEERS_BODY_MIN, so a single peer keeps the card at
        // a sensible ~220–280 px footprint instead of a tiny strip or a huge
        // blank panel.
        let body: iced::Element<'static, AppMessage> = if dep.rows.is_empty() {
            // UI-HOME-16: intentional empty state — small muted icon beside
            // the spec copy, vertically centred in the min-height body so the
            // card stays balanced (never a tiny strip, never a huge blank
            // panel). The text has Fill width + word wrapping so the
            // two-sentence copy reflows at narrow rail widths.
            container(
                Row::new()
                    .push(icon_svg(ICON_FRIEND, TYPO_SM).style(move |t, _| {
                        iced::widget::svg::Style {
                            color: Some(text_muted(t)),
                        }
                    }))
                    .push(Space::new().width(Length::Fixed(SPACE_8)))
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::SupportingText,
                            ONLINE_PEERS_EMPTY_MESSAGE,
                        )
                        .color(text_muted(&theme))
                        .width(Length::Fill)
                        .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                    )
                    .spacing(0)
                    .align_y(Alignment::Center)
                    .width(Length::Fill),
            )
            .width(Length::Fill)
            .height(Length::Fixed(PEERS_BODY_MIN))
            .align_y(Alignment::Center)
            .into()
        } else {
            crate::ui_components::gutter_scrollable(
                Column::with_children(peer_rows)
                    .spacing(SPACE_2)
                    .width(Length::Fill),
            )
            .height(Length::Fixed(Self::online_peers_body_height(
                dep.rows.len(),
            )))
            .width(Length::Fill)
            .into()
        };

        crate::card_shell::CardShell::new("Online Peers", vec![])
            .count(dep.rows.len())
            .count_total(dep.total_friends)
            .on_view_all(AppMessage::OpenFriendRequests)
            .compact_header(dep.compact_header)
            .body(body)
            .background_opacity(f32::from_bits(dep.home_menu_item_opacity_bits))
            .build(&theme)
    }

    /// Content-driven height of the Online Peers body (px): the shorter of
    /// the row content and the five-visible-rows cap, floored at
    /// [`PEERS_BODY_MIN`] so a one-peer card stays intentional.
    fn online_peers_body_height(rows: usize) -> f32 {
        if rows == 0 {
            return PEERS_BODY_MIN;
        }
        let content =
            rows as f32 * crate::card_shell::PEER_ROW_HEIGHT + (rows as f32 - 1.0) * SPACE_2;
        content.min(PEERS_BODY_MAX).max(PEERS_BODY_MIN)
    }

    /// Build the Recent Activity card subtree (memoized via lazy).
    fn view_recent_activity_card(
        dep: &RecentActivityCardData,
    ) -> iced::Element<'static, AppMessage> {
        use iced::widget::{container, row, Space};
        use iced::{Alignment, Length};

        let theme = Self::theme_from_dark(dep.dark_mode);
        // UI-29: recent activity rows are denser than the 48 px peer rows —
        // a compact 32 px row keeps the feed scannable without dead vertical
        // space around the small icon + single-line title.
        const ACTIVITY_ROW_HEIGHT: f32 = 32.0;
        let activity_rows: Vec<iced::Element<'static, AppMessage>> = dep
            .rows
            .iter()
            .map(|event| {
                let ago = crate::presentation::relative_time_from_system(event.timestamp);
                let activity_icon = match event.kind {
                    ActivityKind::Online => ICON_ONLINE,
                    ActivityKind::Offline => ICON_OFFLINE,
                    ActivityKind::FileShared => ICON_FILES,
                    ActivityKind::Message => ICON_CHAT,
                    ActivityKind::Generic => ICON_ACTIVITY,
                };
                // Copy the kind out of the borrowed row so the icon style
                // closure stays 'static (owned values only) — required for
                // the lazy content builder's `Element<'static, _>` return.
                let kind = event.kind;
                // Min-height floor keeps the dense 32 px single-line rhythm;
                // a wrapped description grows the row instead of being
                // clipped (UI-HOME-10: no fixed row height, no clip, no
                // 40-char truncation).
                container(
                row![
                    Space::new()
                        .width(Length::Fixed(0.0))
                        .height(Length::Fixed(ACTIVITY_ROW_HEIGHT)),
                    icon_svg(activity_icon, TYPO_SM).style(move |t, _| {
                        iced::widget::svg::Style {
                            color: Some(if kind == ActivityKind::Online {
                                accent_green(t)
                            } else {
                                text_muted(t)
                            }),
                        }
                    }),
                    container(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Body,
                            event.description.clone(),
                        )
                        .color(text_system(&theme))
                        .width(Length::Fill)
                        .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                    )
                    .width(Length::Fill),
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::Metadata,
                        ago,
                    )
                    .color(text_muted(&theme)),
                ]
                .spacing(SPACE_6)
                .align_y(Alignment::Center),
            )
            .width(Length::Fill)
            .padding([0.0, SPACE_8])
            .align_y(Alignment::Center)
            .into()
            })
            .collect();

        CardShell::new("Recent Activity", activity_rows)
            .count(dep.total)
            .empty_icon(
                icon_svg(ICON_ACTIVITY, TYPO_SM).style(move |t, _| {
                    iced::widget::svg::Style {
                        color: Some(text_muted(t)),
                    }
                }).into(),
            )
            .empty_message(RECENT_ACTIVITY_EMPTY_MESSAGE)
            .compact_header(dep.compact_header)
            .max_height(180.0)
            .background_opacity(f32::from_bits(dep.home_menu_item_opacity_bits))
            .build(&theme)
    }

    /// Build the Tunnels card subtree (memoized via lazy).
    fn view_tunnels_card(dep: &TunnelsCardData) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, row, Column, Space};
        use iced::{Alignment, Length};

        let theme = Self::theme_from_dark(dep.dark_mode);
        let tunnel_rows: Vec<iced::Element<'static, AppMessage>> = dep
            .rows
            .iter()
            .map(|tunnel| {
                let status = if tunnel.expired {
                    "Expired"
                } else {
                    tunnel.status.label()
                };
                let status_color = if tunnel.expired {
                    text_muted(&theme)
                } else {
                    match tunnel.status {
                        TunnelStatus::Active => accent_primary(&theme),
                        TunnelStatus::Connecting => color_warning(&theme),
                        TunnelStatus::Connected => accent_green(&theme),
                        TunnelStatus::Revoked => text_muted(&theme),
                        TunnelStatus::Failed => color_error(&theme),
                        TunnelStatus::Disconnected => text_muted(&theme),
                    }
                };
                container(
                    row![
                        // Min-height floor keeps the 48 px single-line rhythm;
                        // a long tunnel name / endpoint wraps and grows the
                        // row instead of being clipped (UI-HOME-10).
                        Space::new()
                            .width(Length::Fixed(0.0))
                            .height(Length::Fixed(crate::card_shell::CARD_ROW_HEIGHT)),
                        icon_svg(ICON_LOCK, TYPO_SM).style(move |t, _| {
                            iced::widget::svg::Style {
                                color: Some(status_color),
                            }
                        }),
                        Column::new()
                            .push(
                                crate::fonts::type_role_text(
                                    crate::fonts::TypeRole::Body,
                                    tunnel.name.clone(),
                                )
                                .color(text_system(&theme))
                                .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                            )
                            .push(
                                // host:port — genuine technical value → JetBrains Mono.
                                crate::fonts::type_role_text(
                                    crate::fonts::TypeRole::TechnicalValue,
                                    tunnel.endpoint.clone(),
                                )
                                .color(text_muted(&theme))
                                .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                            )
                            .spacing(SPACE_2)
                            .align_x(Alignment::Start)
                            .width(Length::Fill),
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Metadata,
                            status,
                        )
                        .color(status_color),
                        button(
                            Icon::Close
                                .build()
                                .size(IconSize::Xs)
                                .destructive(true)
                                .build()
                        )
                        .on_press(AppMessage::CloseTunnel(tunnel.id))
                        .padding([SPACE_2, SPACE_6])
                        .style(BUTTON_GHOST_BG),
                    ]
                    .spacing(SPACE_6)
                    .align_y(Alignment::Center),
                )
                .width(Length::Fill)
                .align_y(Alignment::Center)
                .into()
            })
            .collect();

        // UI-HOME-16: when the list is empty the header action label becomes
        // "Create tunnel" (the dialog the copy points at) instead of the
        // misleading "View all"; the destination is unchanged.
        let header_action_label = if dep.rows.is_empty() {
            "Create tunnel"
        } else {
            "View all"
        };

        crate::card_shell::CardShell::new("Tunnels", tunnel_rows)
            .count(dep.rows.len())
            .header_action(header_action_label, AppMessage::ShowCreateTunnelDialog)
            .empty_icon(
                icon_svg(ICON_LOCK, TYPO_SM).style(move |t, _| {
                    iced::widget::svg::Style {
                        color: Some(text_muted(t)),
                    }
                }).into(),
            )
            .empty_message(TUNNELS_EMPTY_MESSAGE)
            .compact_header(dep.compact_header)
            .max_height(120.0)
            .background_opacity(f32::from_bits(dep.home_menu_item_opacity_bits))
            .build(&theme)
    }

    /// Header-action label for the Tunnels card: "Create tunnel" when the
    /// list is empty (the dialog the empty copy points at), "View all"
    /// once live tunnels exist. The destination is the same in both cases
    /// (`ShowCreateTunnelDialog`).
    fn tunnels_header_action_label(rows: usize) -> &'static str {
        if rows == 0 {
            "Create tunnel"
        } else {
            "View all"
        }
    }

    // ── Main panel (empty state — landing screen) ─────────────────────

    /// Landing screen shown when no conversation is selected.
    /// Redesigned: connection status first, then actions, then activity.
    fn view_main_empty_state(&self) -> iced::Element<'_, AppMessage> {
        let dep = self.chat_list_dependency();
        iced::widget::lazy(dep, Self::view_chat_list_content).into()
    }

    /// Builds the ChatList (home / empty-state) screen's renderable snapshot.
    fn chat_list_dependency(&self) -> ChatListDependency {
        let has_peer_connections =
            !self.neighbors.is_empty() || self.relayed_peers > 0 || self.direct_peers > 0;
        let connected_age_secs = self.mesh_connected_at.map(|t| {
            Instant::now()
                .saturating_duration_since(t)
                .as_secs()
        });
        // Newest mesh events first (the log pushes to the back), capped at the
        // number the card renders. Age is captured here so the snapshot stays
        // Hash/Eq-compatible; the per-second ActivityTick rebuild keeps ages
        // fresh.
        let now = Instant::now();
        let mesh_events: Vec<MeshEventRow> = self
            .mesh_event_log
            .iter()
            .rev()
            .take(4)
            .map(|event| MeshEventRow {
                message: event.message.clone(),
                age_secs: now.saturating_duration_since(event.recorded_at).as_secs(),
            })
            .collect();
        ChatListDependency {
            dark_mode: self.dark_mode,
            window_width_bits: (self.window_width * 100.0) as u32,
            mesh_health: MeshHealthSnapshot::from(&self.mesh_health),
            main_screen_reconnect_frame: self.main_screen_reconnect_frame as u32,
            local_label: self.local_label.clone(),
            time_of_day_greeting: self.time_of_day_greeting().to_string(),
            has_peer_connections,
            sender_ready: self.sender.is_some(),
            direct_peers: self.direct_peers as u32,
            relayed_peers: self.relayed_peers as u32,
            neighbors_len: self.neighbors.len() as u32,
            connected_age_secs,
            mesh_events,
            online: self.online_peers_card_data(),
            activity: self.recent_activity_card_data(),
            tunnels: self.tunnels_card_data(),
            home_menu_item_opacity_bits: self.home_menu_item_opacity.to_bits(),
        }
    }

    /// Static renderer for the ChatList (home / empty-state) screen, driven by
    /// [`ChatListDependency`] so `iced::widget::lazy` can cache the whole
    /// screen while any of its rendered slices is unchanged.
    fn view_chat_list_content(dep: &ChatListDependency) -> iced::Element<'static, AppMessage> {
        use iced::widget::{button, container, row, Column, Row, Space};
        use iced::{Alignment, Length};

        let window_width = dep.window_width_bits as f32 / 100.0;
        let theme = Self::theme_from_dark(dep.dark_mode);
        // UI-HOME-15: all home breakpoints are based on the dashboard's
        // available *content* width (window minus sidebar, divider and page
        // padding), never the raw window width — the sidebar eats
        // 288–320 px and would otherwise starve the grid on narrow windows.
        let content_width = crate::design_tokens::home_content_width(window_width);
        let compact_header =
            content_width < crate::design_tokens::HOME_COMPACT_HEADER_CONTENT;

        // HOME-01: opacity of home menu/action card backgrounds over the
        // home background image (1.0 = fully opaque; lower = translucent).
        let home_menu_opacity = f32::from_bits(dep.home_menu_item_opacity_bits);

        // ── Connection state (single source of truth) ──
        let has_peer_connections = dep.has_peer_connections;
        let relay_reachable = dep.sender_ready || has_peer_connections;
        let mesh_health = dep.mesh_health.as_mesh_health();
        let variant =
            home_connection_variant(&mesh_health, has_peer_connections, relay_reachable);

        // ── Hero variant visuals (truthful, from the pure mapping above) ──
        let (hero_icon, hero_color, headline): (&[u8], fn(&iced::Theme) -> iced::Color, String) =
            match variant {
                HomeConnectionVariant::Starting => {
                    const RECONNECT_DOTS: [&str; 4] =
                        ["\u{280B}", "\u{2819}", "\u{2839}", "\u{2838}"];
                    let dot = RECONNECT_DOTS
                        [(dep.main_screen_reconnect_frame as usize) % RECONNECT_DOTS.len()];
                    (ICON_RETRY, color_warning, format!("Starting Boru {dot}"))
                }
                HomeConnectionVariant::Connecting => (
                    ICON_RETRY,
                    color_warning,
                    "Connecting \u{2014} waiting for peers\u{2026}".to_string(),
                ),
                HomeConnectionVariant::Ready => (
                    ICON_CHECK,
                    accent_green,
                    "Boru is connected and ready.".to_string(),
                ),
                HomeConnectionVariant::Degraded => {
                    let reason = match &mesh_health {
                        MeshHealth::Degraded(r) => r.clone(),
                        _ => String::new(),
                    };
                    (
                        ICON_MESH,
                        color_warning,
                        format!("Mesh degraded \u{2014} {reason}"),
                    )
                }
                HomeConnectionVariant::Offline => {
                    let reason = match &mesh_health {
                        MeshHealth::Offline(r) => r.clone(),
                        _ => String::new(),
                    };
                    (
                        ICON_OFFLINE,
                        color_error,
                        format!("Boru is offline \u{2014} {reason}"),
                    )
                }
            };
        let show_retry = matches!(variant, HomeConnectionVariant::Offline);
        let show_details = matches!(
            variant,
            HomeConnectionVariant::Offline | HomeConnectionVariant::Degraded
        );
        // Compact status pill label for the page header (Figure 3).
        let pill_label = match variant {
            HomeConnectionVariant::Starting => "Starting",
            HomeConnectionVariant::Connecting => "Connecting",
            HomeConnectionVariant::Ready => "Connected",
            HomeConnectionVariant::Degraded => "Degraded",
            HomeConnectionVariant::Offline => "Offline",
        };

        // ── Greeting (page header) ──
        // UI-HOME-12: display_heading — Archivo SemiCondensed Bold 32 px,
        // 1.2 line height (via TypeRole::DisplayHeading).
        let display_name = if dep.local_label.is_empty() {
            "there"
        } else {
            &dep.local_label
        };
        let greeting = crate::fonts::type_role_text_lh(
            crate::fonts::TypeRole::DisplayHeading,
            format!("Good {}, {display_name}", dep.time_of_day_greeting),
            1.2,
        )
        .color(crate::design_tokens::text_primary(&theme))
        .width(Length::Fill)
        // A long display name (e.g. a bare peer key) must wrap inside the
        // header instead of overflowing it (UI-HOME-10).
        .wrapping(iced::widget::text::Wrapping::WordOrGlyph);
        // Subtitle — IBM Plex Sans Regular at the UI-HOME-02 size token
        // (16 px; the canonical `body` role is 15 px, plan band 15–17 px).
        let welcome_line = crate::fonts::type_role_text(
            crate::fonts::TypeRole::Body,
            "Welcome to Boru",
        )
        .size(crate::fonts::HOME_SUBTITLE)
        .color(text_secondary(&theme))
        .width(Length::Fill);

        // ── Status pill (page header right, compact) ──
        // ~36 px tall (10 px vertical padding + 16 px content) per the
        // UI-HOME-02 mockup range (36–40 px).
        // UI-HOME-09: pill vertical padding on the shared scale (SPACE_12 →
        // ~40 px tall, still within the UI-HOME-02 36–40 px band; was
        // SPACE_10, off the scale).
        let status_pill = container(
            row![
                icon_svg(hero_icon, TYPO_SM).style(move |t, _| iced::widget::svg::Style {
                    color: Some(hero_color(t)),
                }),
                Space::new().width(Length::Fixed(SPACE_8)),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, pill_label)
                    .color(hero_color(&theme)),
            ]
            .spacing(0)
            .align_y(Alignment::Center),
        )
        .padding([SPACE_12, SPACE_12])
        .style(move |t| {
            let mut bg = bg_surface(t);
            bg.a *= home_menu_opacity;
            iced::widget::container::Style {
                background: Some(iced::Background::Color(bg)),
                border: iced::Border {
                    color: hero_color(t),
                    width: 1.0,
                    radius: SPACE_16.into(),
                },
                ..Default::default()
            }
        });

        // ── Large connection hero card (Figure 3) ──
        // UI-HOME-09: icon-container standardised on tokens — AVATAR_MD for
        // the 48 px circle (radius = half) and IconSize::Lg for the glyph
        // (was a raw 48.0 / 24.0 / 22.0 literal set).
        let hero_badge =
            container(
                icon_svg(hero_icon, IconSize::Lg.px()).style(move |t, _| {
                    iced::widget::svg::Style {
                        color: Some(iced::Color::WHITE),
                    }
                }),
            )
            .width(Length::Fixed(crate::design_tokens::AVATAR_MD))
            .height(Length::Fixed(crate::design_tokens::AVATAR_MD))
            .style(move |t| iced::widget::container::Style {
                background: Some(iced::Background::Color(hero_color(t))),
                border: iced::Border {
                    radius: (crate::design_tokens::AVATAR_MD / 2.0).into(),
                    ..Default::default()
                },
                ..Default::default()
            });

        let mut hero_actions = Row::new().spacing(SPACE_8);
        if show_retry {
            hero_actions = hero_actions.push(
                button(crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Retry",
                ))
                .on_press(AppMessage::RetryConnection)
                .padding([SPACE_6, SPACE_12])
                .style(BUTTON_PRIMARY),
            );
        }
        if show_details {
            hero_actions = hero_actions.push(
                button(crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Details",
                ))
                .on_press(AppMessage::OpenConnectionDetails)
                .padding([SPACE_6, SPACE_12])
                .style(BUTTON_OUTLINE),
            );
        }

        let mut hero_text = Column::new()
            .push(
                // Connection heading — section_title (IBM Plex Sans SemiBold 20).
                // Fills the hero text column and glyph-wraps a long degraded /
                // offline reason instead of overflowing the card (UI-HOME-10).
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SectionTitle,
                    headline.clone(),
                )
                .color(hero_color(&theme))
                .width(Length::Fill)
                .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
            )
            .push(Space::new().height(Length::Fixed(SPACE_4)))
            .push(
                // Body copy — IBM Plex Sans Regular 15, 1.45 line height.
                crate::fonts::type_role_text_lh(
                    crate::fonts::TypeRole::Body,
                    "Private communication, peer to peer.",
                    1.45,
                )
                .color(text_secondary(&theme)),
            );
        if show_retry || show_details {
            hero_text = hero_text
                .push(Space::new().height(Length::Fixed(SPACE_12)))
                .push(hero_actions);
        }
        let hero_text = hero_text.spacing(0).width(Length::Fill);

        // ── Large connection hero card (Figure 3 / UI-HOME-04) ──
        // Left message group (state badge + headline + subtitle + actions)
        // balanced against a right decorative mesh illustration group. The
        // card keeps the approved large-green proportions: minimum height
        // ~244 px (HERO_MIN_CONTENT_HEIGHT + SPACE_32 padding), ~32 px
        // padding, light green-tinted surface when Ready, thin green-grey
        // border and RADIUS_CARD through the shared card_style.
        //
        // The minimum height is content-driven, not a clip: a zero-width
        // Space with the target content height sits inside the row, so the
        // row is at least that tall but grows if a long degraded/offline
        // reason wraps the headline. Nothing is clipped.

        // Left message group: circular state icon + headline/subtitle,
        // vertically centred against the card's minimum height.
        let hero_left_group = Row::new()
            .push(hero_badge)
            .push(Space::new().width(Length::Fixed(SPACE_16)))
            .push(hero_text)
            .spacing(0)
            .align_y(Alignment::Center)
            .width(Length::Fill);

        // Right illustration group: static low-contrast node-graph, scaled
        // proportionally (native 220×150 → 205×140), inset from the card
        // edge by the card padding. UI-HOME-15: the illustration is shown at
        // full size on wide content, scaled down 0.8× in the medium band,
        // and hidden below the minimum readable content width so the
        // connection text never gets starved.
        let hero_illustration = if content_width
            < crate::design_tokens::HOME_ILLUSTRATION_HIDE_CONTENT
        {
            None
        } else {
            let (iw, ih) = if content_width
                >= crate::design_tokens::HOME_ILLUSTRATION_FULL_CONTENT
            {
                (205.0, 140.0)
            } else {
                (164.0, 112.0) // 0.8× scale
            };
            Some(
                iced::widget::svg(iced::widget::svg::Handle::from_memory(NETWORK_MOTIF))
                    .width(Length::Fixed(iw))
                    .height(Length::Fixed(ih))
                    .style(|_t, _s| iced::widget::svg::Style { color: None }),
            )
        };

        let mut hero_row = Row::new()
            // Zero-width spacer drives the card's minimum height; the row
            // grows with content (no fixed height, no clipping).
            .push(
                Space::new()
                    .width(Length::Fixed(0.0))
                    .height(Length::Fixed(HERO_MIN_CONTENT_HEIGHT)),
            )
            .push(hero_left_group)
            .spacing(0)
            .align_y(Alignment::Center)
            .width(Length::Fill);
        if let Some(illustration) = hero_illustration {
            hero_row = hero_row
                .push(Space::new().width(Length::Fixed(SPACE_16)))
                .push(illustration);
        }

        let hero_card = container(hero_row)
            .padding(SPACE_32)
            .width(Length::Fill)
            // Hero variant of the shared dashboard-card surface: same
            // border/radius/shadow as every home card (card_style), with
            // the background overridden to the primary soft tint when the
            // mesh is Ready.
            .style(move |t| {
                let mut style = crate::design_tokens::card_style(t);
                let mut bg = if matches!(variant, HomeConnectionVariant::Ready) {
                    crate::design_tokens::primary_soft(t)
                } else {
                    bg_surface(t)
                };
                bg.a *= home_menu_opacity;
                style.background = Some(iced::Background::Color(bg));
                style
            });

        // ── Mesh Health card ──
        // UI-HOME-05: full dashboard card. Header carries a mesh glyph +
        // title + real status badge + the existing "View details" action.
        // Body shows the live status row, three real connection counts
        // (neighbors / direct / relayed), lobby state + connection duration
        // when available, and a short recent-events list fed from the same
        // bounded mesh event log the rest of the app uses — no invented
        // statistics. UI-28 keeps transient startup lines from lingering:
        // the watchdog clears "Starting up...", "Connecting to lobby...",
        // "Connected to lobby..." and "Subscribing to..." once the mesh is
        // Good, so the log stays truthful.
        let (health_label, health_color): (&str, fn(&iced::Theme) -> Color) =
            match &mesh_health {
                MeshHealth::Good => ("Healthy", accent_green),
                MeshHealth::Degraded(_) => ("Degraded", color_warning),
                MeshHealth::Offline(_) => ("Offline", color_error),
            };
        let mesh_has_peers = dep.has_peer_connections;
        let mesh_relay_reachable = dep.sender_ready || mesh_has_peers;
        let mesh_variant =
            home_connection_variant(&mesh_health, mesh_has_peers, mesh_relay_reachable);

        let (status_icon, status_color, status_label): (
            &[u8],
            fn(&iced::Theme) -> Color,
            String,
        ) = match mesh_variant {
            HomeConnectionVariant::Starting => {
                (ICON_RETRY, color_warning, "Starting up…".to_string())
            }
            HomeConnectionVariant::Connecting => (
                ICON_RETRY,
                color_warning,
                "Connecting — waiting for peers…".to_string(),
            ),
            HomeConnectionVariant::Ready => (ICON_CHECK, accent_green, "Connected".to_string()),
            HomeConnectionVariant::Degraded => {
                let reason = match &mesh_health {
                    MeshHealth::Degraded(r) => r.clone(),
                    _ => String::new(),
                };
                (ICON_MESH, color_warning, format!("Degraded — {reason}"))
            }
            HomeConnectionVariant::Offline => {
                let reason = match &mesh_health {
                    MeshHealth::Offline(r) => r.clone(),
                    _ => String::new(),
                };
                (ICON_OFFLINE, color_error, format!("Offline — {reason}"))
            }
        };

        // Secondary line: current peer counts, plus connection time once the
        // mesh is healthy (mesh_connected_at is maintained by the watchdog).
        let status_detail = match mesh_variant {
            HomeConnectionVariant::Starting => "Establishing the mesh…".to_string(),
            HomeConnectionVariant::Connecting => {
                "Waiting for peers to join the mesh".to_string()
            }
            _ => {
                let mut parts = vec![format!(
                    "{} direct · {} relayed · {} neighbors",
                    dep.direct_peers,
                    dep.relayed_peers,
                    dep.neighbors_len,
                )];
                if let Some(secs) = dep.connected_age_secs {
                    let duration = if secs < 60 {
                        format!("connected {secs}s")
                    } else if secs < 3600 {
                        format!("connected {}m {}s", secs / 60, secs % 60)
                    } else {
                        format!("connected {}h {}m", secs / 3600, (secs % 3600) / 60)
                    };
                    parts.push(duration);
                }
                parts.join("  ·  ")
            }
        };

        // Status pill in the header reports the mesh health state using the
        // same palette as the footer strip below the dashboard.
        let mesh_badge_kind = match &mesh_health {
            MeshHealth::Good => StatusBadgeKind::Success,
            MeshHealth::Degraded(_) => StatusBadgeKind::Warning,
            MeshHealth::Offline(_) => StatusBadgeKind::Danger,
        };

        // Body: status icon + label + detail (content-driven — grows with
        // the status detail text instead of clipping).
        let mesh_status_row = Row::new()
            .push(icon_svg(status_icon, TYPO_MD).style(move |t, _| {
                iced::widget::svg::Style {
                    color: Some(status_color(t)),
                }
            }))
            .push(Space::new().width(Length::Fixed(SPACE_8)))
            .push(
                Column::new()
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::BodyEmphasised,
                            status_label.clone(),
                        )
                        .color(status_color(&theme))
                        .width(Length::Fill)
                        .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                    )
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::SupportingText,
                            status_detail,
                        )
                        .color(text_muted(&theme))
                        .width(Length::Fill)
                        .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                    )
                    .width(Length::Fill),
            )
            .spacing(0)
            .align_y(Alignment::Center)
            .width(Length::Fill);

        // Live connection-count stat blocks (neighbors / direct / relayed).
        // Values come straight from the dependency snapshot — no fabricated
        // numbers; three labelled tiles make the real counts readable at a
        // glance instead of hiding them inside a sentence.
        let mesh_stat_block = |label: &'static str, value: u32| -> iced::Element<'static, AppMessage> {
            let tile = Column::new()
                .push(
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::BodyEmphasised,
                        value.to_string(),
                    )
                    .color(crate::design_tokens::text_primary(&theme)),
                )
                .push(
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::Metadata,
                        label,
                    )
                    .color(text_muted(&theme)),
                )
                .spacing(SPACE_2)
                .align_x(Alignment::Center)
                .width(Length::Fill);
            container(tile)
                .padding([SPACE_6, SPACE_4])
                .width(Length::Fill)
                .style(move |t| container::Style {
                    background: Some(iced::Background::Color(
                        crate::design_tokens::surface_hover(t),
                    )),
                    border: iced::Border {
                        radius: crate::design_tokens::RADIUS_SM.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                })
                .into()
        };
        let mesh_stats_row = Row::new()
            .push(mesh_stat_block("Neighbors", dep.neighbors_len))
            // UI-HOME-09: stat-tile gaps on the shared scale (SPACE_8; was
            // SPACE_6, off the scale).
            .push(Space::new().width(Length::Fixed(SPACE_8)))
            .push(mesh_stat_block("Direct", dep.direct_peers))
            .push(Space::new().width(Length::Fixed(SPACE_8)))
            .push(mesh_stat_block("Relayed", dep.relayed_peers))
            .spacing(0)
            .width(Length::Fill);

        // Lobby state + connection duration line. Lobby state derives from
        // the real gossip sender: when the sender subscription is up the app
        // is in the lobby, otherwise it is still joining. Duration is shown
        // only when the watchdog has a connected timestamp.
        let lobby_label = if dep.sender_ready {
            "Lobby: connected".to_string()
        } else {
            "Lobby: connecting…".to_string()
        };
        let mut lobby_parts = vec![lobby_label];
        if let Some(secs) = dep.connected_age_secs {
            let duration = if secs < 60 {
                format!("connected {secs}s")
            } else if secs < 3600 {
                format!("connected {}m {}s", secs / 60, secs % 60)
            } else {
                format!("connected {}h {}m", secs / 3600, (secs % 3600) / 60)
            };
            lobby_parts.push(duration);
        }
        let mesh_lobby_row = Row::new()
            .push(icon_svg(ICON_MESH, TYPO_XS).style(move |t, _| {
                iced::widget::svg::Style {
                    color: Some(text_muted(t)),
                }
            }))
            .push(Space::new().width(Length::Fixed(SPACE_6)))
            .push(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SupportingText,
                    lobby_parts.join("  ·  "),
                )
                .color(text_muted(&theme))
                .width(Length::Fill)
                .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
            )
            .spacing(0)
            .align_y(Alignment::Center)
            .width(Length::Fill);

        // Recent mesh events — a short, readable list from the real bounded
        // log. Each row: small status icon + description + relative time.
        // `dep.mesh_events` is already newest-first and capped at 4 in the
        // dependency selector, so the card stays content-driven (no fixed
        // heights, no hidden overflow).
        let events_header = crate::fonts::type_role_text(
            crate::fonts::TypeRole::Metadata,
            "Recent events".to_uppercase(),
        )
        .color(text_muted(&theme));
        let event_rows: Vec<iced::Element<'static, AppMessage>> = dep
            .mesh_events
            .iter()
            .map(|event| {
                let tone = mesh_event_tone(&event.message);
                let (event_icon, event_color) = mesh_event_visual(tone);
                let ago =
                    crate::presentation::relative_age_secs(event.age_secs, 10);
                container(
                    Row::new()
                        .push(icon_svg(event_icon, TYPO_SM).style(move |t, _| {
                            iced::widget::svg::Style {
                                color: Some(event_color(t)),
                            }
                        }))
                        .push(Space::new().width(Length::Fixed(SPACE_6)))
                        .push(
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Body,
                                event.message.clone(),
                            )
                            .color(text_system(&theme))
                            .width(Length::Fill)
                            .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                        )
                        .push(
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Metadata,
                                ago,
                            )
                            .color(text_muted(&theme)),
                        )
                        .spacing(SPACE_6)
                        .align_y(Alignment::Center),
                )
                .width(Length::Fill)
                .padding([SPACE_2, 0.0])
                .into()
            })
            .collect();
        let events_body: iced::Element<'static, AppMessage> = if event_rows.is_empty() {
            // Intentional no-events state (UI-HOME-16): keep the connection
            // summary above and explain that there are no recent mesh events
            // with the same small-icon + muted-text treatment the rail cards
            // use. The text wraps at narrow content widths.
            Row::new()
                .push(icon_svg(ICON_ACTIVITY, TYPO_SM).style(move |t, _| {
                    iced::widget::svg::Style {
                        color: Some(text_muted(t)),
                    }
                }))
                .push(Space::new().width(Length::Fixed(SPACE_8)))
                .push(
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::SupportingText,
                        MESH_EVENTS_EMPTY_MESSAGE,
                    )
                    .color(text_muted(&theme))
                    .width(Length::Fill)
                    .wrapping(iced::widget::text::Wrapping::WordOrGlyph),
                )
                .spacing(0)
                .align_y(Alignment::Center)
                .width(Length::Fill)
                .into()
        } else {
            Column::with_children(event_rows)
                .spacing(SPACE_2)
                .width(Length::Fill)
                .into()
        };

        let mesh_body = Column::new()
            .push(mesh_status_row)
            // UI-HOME-09: structural body gaps on the shared scale (SPACE_12
            // between blocks; was SPACE_10, off the scale).
            .push(Space::new().height(Length::Fixed(SPACE_12)))
            .push(mesh_stats_row)
            .push(Space::new().height(Length::Fixed(SPACE_8)))
            .push(mesh_lobby_row)
            .push(Space::new().height(Length::Fixed(SPACE_12)))
            .push(crate::ui_components::divider())
            .push(Space::new().height(Length::Fixed(SPACE_8)))
            .push(events_header)
            .push(Space::new().height(Length::Fixed(SPACE_4)))
            .push(events_body)
            .spacing(0)
            .width(Length::Fill);

        let mesh_card = CardShell::new("Mesh Health", vec![])
            .title_case(false)
            .header_icon(icon_svg(ICON_MESH, TYPO_MD).style(move |t, _| {
                iced::widget::svg::Style {
                    color: Some(health_color(t)),
                }
            }).into())
            .subtitle("Current connection status")
            .status_badge(health_label, mesh_badge_kind)
            .header_action("View details", AppMessage::OpenConnectionDetails)
            .compact_header(compact_header)
            .body(mesh_body.into())
            .background_opacity(home_menu_opacity)
            .build(&theme);

        // ── Quick actions: four equal, full-card targets (Figure 3) ──
        let action_grid =
            crate::quick_actions::quick_action_grid(content_width, &theme, home_menu_opacity);

        // DLMGR-01: home entry point — a compact outline button beside the
        // status pill opens the Download Manager (all active transfers in
        // both directions). Static renderer: no dependency data needed, just
        // a message dispatch.
        let download_manager_btn = button(
            Row::new()
                .push(
                    Icon::Download
                        .build()
                        .size(crate::icon_system::IconSize::Xs)
                        .color_fn(crate::design_tokens::text_muted)
                        .build(),
                )
                .push(
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::ButtonLabel,
                        "Download Manager",
                    ),
                )
                .spacing(SPACE_4)
                .align_y(Alignment::Center),
        )
        .on_press(AppMessage::OpenDownloadManager)
        .padding([SPACE_6, SPACE_12])
        .style(BUTTON_OUTLINE);

        // ── Right rail: loading treatment decision (t_0441a1dc) ──
        // No skeleton/shimmer loading is used for the three rail cards, by
        // design. Every data source here is synchronously available at first
        // render: Online Peers reads `self.friends` plus the presence map
        // seeded from persisted friend status during IcedChat::new; Recent
        // Activity reads the in-memory ring buffer; Tunnels reads
        // TunnelService::list_tunnels() (a synchronous RwLock read of the
        // live in-memory registry). There is no mount-time fetch of any of
        // these. The only real asynchronous startup window (endpoint, DHT,
        // protocol handlers, friend load) runs before the Iced window opens
        // and is covered by the native splash window in main.rs; later
        // presence/activity/tunnel updates arrive as event-driven messages
        // that redraw these cards synchronously. A skeleton would therefore
        // only appear by faking an async delay, which the task explicitly
        // forbids — so rows render real data immediately and fill in
        // progressively (e.g. profile images arrive async and replace the
        // initials fallback when downloaded). Full rationale in
        // docs/ui-redesign/evidence/ui-skeletons/README.md.

        // ── Right column: Online Peers / Recent Activity / Tunnels ──
        // Each card is built by a fine-grained selector (see the selector
        // methods above) and wrapped in `iced::widget::lazy`. The lazy widget
        // compares the fresh selector value — a PartialEq snapshot of exactly
        // that card's state slice — with the previous frame and reuses the
        // already-built subtree when nothing in the slice changed. A peer
        // presence change therefore rebuilds only the Online Peers card, an
        // activity push only Recent Activity, and a tunnel status change only
        // Tunnels. The per-second ActivityTick bumps `activity_tick`, which
        // the Recent Activity and Tunnels dependencies include (fresh relative
        // timestamps / truthful expiry flips) but the Online Peers dependency
        // deliberately excludes — the peers card never rebuilds on an idle
        // tick.
        let online_card =
            iced::widget::lazy(dep.online.clone(), Self::view_online_peers_card);
        let activity_card =
            iced::widget::lazy(dep.activity.clone(), Self::view_recent_activity_card);
        let tunnels_card = iced::widget::lazy(dep.tunnels.clone(), Self::view_tunnels_card);

        // Right rail: 20 px vertical card gaps (UI-HOME-02: 20–24 px).
        let right_col = Column::new()
            .push(online_card)
            .push(Space::new().height(Length::Fixed(SPACE_20)))
            .push(activity_card)
            .push(Space::new().height(Length::Fixed(SPACE_20)))
            .push(tunnels_card)
            .spacing(0)
            .width(Length::Fill);

        // ── Page header: greeting + welcome + status pill (Figure 3) ──
        // UI-HOME-15: on narrow content the pill stacks under the greeting
        // (left-aligned) instead of squeezing it; on wider content it keeps
        // the approved top-right position.
        let page_header: iced::Element<'static, AppMessage> = if compact_header {
            Column::new()
                .push(
                    Column::new()
                        .push(greeting)
                        // Greeting → welcome gap. UI-HOME-09: shared-scale
                        // SPACE_4 (was SPACE_2, off the scale).
                        .push(Space::new().height(Length::Fixed(SPACE_4)))
                        .push(welcome_line)
                        .spacing(0)
                        .width(Length::Fill),
                )
                .push(Space::new().height(Length::Fixed(SPACE_12)))
                .push(
                    Row::new()
                        .push(status_pill)
                        .push(Space::new().width(Length::Fixed(SPACE_8)))
                        .push(download_manager_btn)
                        .spacing(0)
                        .align_y(Alignment::Center)
                        .width(Length::Fill),
                )
                .spacing(0)
                .width(Length::Fill)
                .into()
        } else {
            row![
                Column::new()
                    .push(greeting)
                    // Greeting → welcome gap. UI-HOME-09: shared-scale SPACE_4
                    // (was SPACE_2, off the scale).
                    .push(Space::new().height(Length::Fixed(SPACE_4)))
                    .push(welcome_line)
                    .spacing(0)
                    .width(Length::Fill),
                status_pill,
                Space::new().width(Length::Fixed(SPACE_8)),
                download_manager_btn,
            ]
            .spacing(SPACE_8)
            .align_y(Alignment::Center)
            .into()
        };

        // ── Main content: hero + mesh + actions left, activity rail right ──
        // Two-thirds content + one-third activity rail (plan §4): main
        // ~66.7% / right ~33.3% with a 24 px column gap. Below the stack
        // breakpoint the rail collapses BELOW the left column instead of
        // compressing its cards. UI-HOME-15: the breakpoint is content-width
        // based (window minus sidebar/divider/padding), so the fixed 288 px
        // sidebar never forces an early stack.
        let rail_stacked =
            content_width < crate::design_tokens::HOME_TWO_COL_CONTENT;
        let card_gap = SPACE_20; // 20 px vertical card gap (plan: 20–24 px)

        let left_col = Column::new()
            .push(hero_card)
            .push(Space::new().height(Length::Fixed(card_gap)))
            .push(mesh_card)
            .push(Space::new().height(Length::Fixed(card_gap)))
            .push(action_grid)
            .spacing(0)
            .width(Length::Fill);

        let main_content: iced::Element<'_, AppMessage> = if rail_stacked {
            // Narrow: left-column cards first, then the activity rail below.
            Column::new()
                .push(left_col)
                .push(Space::new().height(Length::Fixed(card_gap)))
                .push(right_col)
                .spacing(0)
                .width(Length::Fill)
                .into()
        } else {
            // Wide: two-column dashboard grid, both columns aligned top.
            Row::new()
                .push(container(left_col).width(Length::FillPortion(2)))
                .push(Space::new().width(Length::Fixed(SPACE_24)))
                .push(container(right_col).width(Length::FillPortion(1)))
                .spacing(0)
                .align_y(Alignment::Start)
                .width(Length::Fill)
                .into()
        };

        // ── Connection footer: one truthful, compact status strip ──
        // Encryption status is derived from actual connection state: iroh
        // always transports over QUIC (encrypted), so we report "QUIC encrypted"
        // only when a peer connection exists, avoiding a blanket E2E claim.
        let encryption_label = if dep.direct_peers > 0 || dep.relayed_peers > 0 {
            "QUIC encrypted"
        } else {
            "Idle"
        };
        let footer = connection_footer(
            health_label,
            health_color,
            dep.direct_peers as usize,
            dep.relayed_peers as usize,
            dep.neighbors_len as usize,
            encryption_label,
        );

        // ── Assemble: centred dashboard canvas with responsive padding ──
        // Horizontal 32 px at large widths, 28 px elsewhere; top 28 px below
        // the application header; bottom at least 32 px (UI-HOME-02 plan).
        let h_padding = if crate::design_tokens::is_large(window_width) {
            SPACE_32
        } else {
            SPACE_28
        };

        // UI-HOME-09: page header → dashboard gap on the shared scale.
        // Plan band 28–32 px; SPACE_28 (was SPACE_20, below the band).
        let col = Column::new()
            .push(page_header)
            .push(Space::new().height(Length::Fixed(SPACE_28)))
            .push(main_content)
            .push(Space::new().height(Length::Fixed(SPACE_16)))
            .push(footer)
            .spacing(0)
            .width(Length::Fill);

        // Cap the dashboard width (~1480 px) and centre it in the available
        // content region; vertical page scrolling stays on gutter_scrollable.
        // The max-width only binds on very wide windows (e.g. 1920), where it
        // keeps the grid from stretching edge-to-edge.
        let canvas = container(
            container(col)
                .padding(iced::Padding::from([SPACE_28, h_padding]).bottom(SPACE_32))
                .width(Length::Fill)
                .max_width(crate::design_tokens::DASHBOARD_MAX_WIDTH)
                .height(Length::Fill),
        )
        .width(Length::Fill)
        .align_x(Alignment::Center)
        .height(Length::Fill);

        crate::ui_components::gutter_scrollable(canvas)
            .width(Length::Fill)
            .height(Length::Fill)
            .into()
    }

    // ── Chat panel (main panel when a conversation is selected) ──────────

    /// The chat panel shown in the main panel area when a conversation is active.
    /// Contains header + message log + composer.
    fn view_chat_panel(&self) -> iced::Element<'_, AppMessage> {
        use iced::{widget, Length};

        // Show a loading spinner while the gossip subscription is in flight.
        if self.room_loading {
            const SPINNER_FRAMES: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
            let spinner = SPINNER_FRAMES[self.splash_spinner_frame % SPINNER_FRAMES.len()];
            let theme = self.theme();
            let dark_mode = self.theme() == iced::Theme::Dark;
            return widget::container(
                widget::column![
                    widget::text(spinner)
                        .size(40.0)
                        .color(accent_primary(&theme)),
                    widget::text("Loading conversation\u{2026}")
                        .size(crate::fonts::TypeRole::Body.size_px())
                        .font(crate::fonts::TypeRole::Body.font())
                        .color(Self::muted_color(dark_mode)),
                    widget::text("Setting up your conversation")
                        .size(crate::fonts::TypeRole::SupportingText.size_px())
                        .font(crate::fonts::TypeRole::SupportingText.font())
                        .color(Self::muted_color(dark_mode)),
                ]
                .spacing(SPACE_12)
                .align_x(iced::Alignment::Center),
            )
            .width(Length::Fill)
            .height(Length::Fill)
            .center_x(Length::Fill)
            .center_y(Length::Fill)
            .into();
        }

        // Show a connecting animation when the subscription completed but the
        // gossip sender isn't available yet — the mesh peer hasn't connected.
        if self.sender.is_none() {
            const SPINNER_FRAMES: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
            let spinner = SPINNER_FRAMES[self.connecting_spinner_frame % SPINNER_FRAMES.len()];
            let theme = self.theme();
            let dark_mode = self.theme() == iced::Theme::Dark;
            return widget::container(
                widget::column![
                    widget::text(spinner)
                        .size(40.0)
                        .color(accent_primary(&theme)),
                    widget::text("Connecting…")
                        .size(crate::fonts::TypeRole::Body.size_px())
                        .font(crate::fonts::TypeRole::Body.font())
                        .color(Self::muted_color(dark_mode)),
                    widget::text("The conversation will be ready shortly")
                        .size(crate::fonts::TypeRole::SupportingText.size_px())
                        .font(crate::fonts::TypeRole::SupportingText.font())
                        .color(Self::muted_color(dark_mode)),
                ]
                .spacing(SPACE_8)
                .align_x(iced::Alignment::Center),
            )
            .width(Length::Fill)
            .height(Length::Fill)
            .center_x(Length::Fill)
            .center_y(Length::Fill)
            .into();
        }

        // Keep the header and composer outside the scrollable message log so
        // navigation and sending remain available while reading history. A
        // subtle divider separates the header from the message region.
        //
        // The timeline is the ONLY vertically expanding region: it fills the
        // space between the fixed header and the pinned composer. It is wrapped
        // in a `responsive` widget so `view_chat_log` knows its exact region
        // height — iced only emits `Scrolled` events once content overflows,
        // so a short timeline would otherwise never learn its viewport size
        // and could not bottom-align its content (leaving a dead area below
        // the last message).
        //
        // The restrained footer/status line (plan UI-16) sits below the
        // composer, separated by a small gap, and reports complementary
        // route/peer state — the header already owns presence + encryption
        // (direct) or member count (group), so nothing is duplicated.
        let content = widget::column![
            self.view_chat_header(),
            divider(&self.theme()),
            widget::responsive(|size: iced::Size| {
                self.view_chat_log(size.width, size.height).into()
            }),
            self.view_composer(),
            widget::Space::new().height(Length::Fixed(SPACE_8)),
            self.view_chat_footer(),
        ]
        // Make the column itself participate in the parent height
        // negotiation. The responsive timeline can then consume exactly the
        // remaining space after the fixed header and composer have been
        // measured, instead of falling back to the column's intrinsic height.
        .spacing(0)
        .width(Length::Fill)
        .height(Length::Fill);

        let inner = widget::container(content)
            .padding(iced::Padding {
                top: 0.0,
                right: SPACE_16,
                bottom: SPACE_12,
                left: SPACE_16,
            })
            .width(Length::Fill)
            .height(Length::Fill);

        // ── Chat options popover overlay ────────────────────────────
        if self.show_chat_options {
            use iced::widget::Stack;
            use iced::Color;

            let backdrop = widget::button(widget::Space::new())
                .width(Length::Fill)
                .height(Length::Fill)
                .on_press(AppMessage::ToggleChatOptions)
                .style(move |t, _status| iced::widget::button::Style {
                    background: Some(iced::Background::Color(if matches!(t, iced::Theme::Dark) {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.45)
                    } else {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.25)
                    })),
                    ..Default::default()
                });

            let options_panel = self.view_chat_options_popover();

            Stack::new()
                .push(inner)
                .push(backdrop)
                .push(
                    widget::container(options_panel)
                        .width(Length::Fill)
                        .height(Length::Fill)
                        .center_x(Length::Fill)
                        .center_y(Length::Fill),
                )
                .width(Length::Fill)
                .height(Length::Fill)
                .into()
        } else if self.show_chat_search {
            use iced::widget::Stack;
            use iced::Color;

            let backdrop = widget::button(widget::Space::new())
                .width(Length::Fill)
                .height(Length::Fill)
                .on_press(AppMessage::ToggleChatSearch)
                .style(move |t, _status| iced::widget::button::Style {
                    background: Some(iced::Background::Color(if matches!(t, iced::Theme::Dark) {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.35)
                    } else {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.15)
                    })),
                    ..Default::default()
                });

            let search_panel = self.view_chat_search_panel();

            Stack::new()
                .push(inner)
                .push(backdrop)
                .push(
                    widget::container(search_panel)
                        .width(Length::Fill)
                        .padding(iced::Padding {
                            top: 72.0, // below the fixed header
                            right: SPACE_16,
                            bottom: 0.0,
                            left: 0.0,
                        })
                        .align_x(iced::alignment::Horizontal::Right)
                        .align_y(iced::alignment::Vertical::Top),
                )
                .width(Length::Fill)
                .height(Length::Fill)
                .into()
        } else if self.help_visible {
            use iced::widget::Stack;
            use iced::Color;
            let chat_layer = inner;

            let backdrop = widget::button(widget::Space::new())
                .width(Length::Fill)
                .height(Length::Fill)
                .on_press(AppMessage::ToggleHelp)
                .style(move |t, _status| iced::widget::button::Style {
                    background: Some(iced::Background::Color(if matches!(t, iced::Theme::Dark) {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.55)
                    } else {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.35)
                    })),
                    ..Default::default()
                });

            let help_panel = widget::container(self.view_help())
                .width(Length::Shrink)
                .height(Length::Shrink)
                .max_width(480.0)
                .max_height(600.0)
                .style(move |t| iced::widget::container::Style {
                    background: Some(iced::Background::Color(bg_surface(t))),
                    border: iced::Border {
                        radius: SPACE_12.into(),
                        ..Default::default()
                    },
                    shadow: iced::Shadow {
                        color: Color::from_rgba(0.0, 0.0, 0.0, 0.3),
                        offset: iced::Vector::new(0.0, 4.0),
                        blur_radius: 24.0,
                    },
                    ..Default::default()
                });

            Stack::new()
                .push(chat_layer)
                .push(backdrop)
                .push(
                    widget::container(help_panel)
                        .width(Length::Fill)
                        .height(Length::Fill)
                        .center_x(Length::Fill)
                        .center_y(Length::Fill),
                )
                .width(Length::Fill)
                .height(Length::Fill)
                .into()
        } else if self.show_member_list {
            use iced::widget::Stack;
            use iced::Color;
            let chat_layer = inner;

            let backdrop = widget::button(widget::Space::new())
                .width(Length::Fill)
                .height(Length::Fill)
                .on_press(AppMessage::ToggleMemberList)
                .style(move |t, _status| iced::widget::button::Style {
                    background: Some(iced::Background::Color(if matches!(t, iced::Theme::Dark) {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.45)
                    } else {
                        Color::from_rgba(0.0, 0.0, 0.0, 0.25)
                    })),
                    ..Default::default()
                });

            let member_list_panel = widget::container(self.view_group_member_list())
                .width(Length::Fill)
                .height(Length::Fill)
                .center_x(Length::Fill)
                .center_y(Length::Fill);

            Stack::new()
                .push(chat_layer)
                .push(backdrop)
                .push(member_list_panel)
                .width(Length::Fill)
                .height(Length::Fill)
                .into()
        } else {
            // ── Right-click context menu overlay ────────────────────
            if let Some((idx, _, _, kind)) = self.context_menu {
                use iced::widget::Stack;
                let menu = self.view_context_menu(idx, kind);
                Stack::new()
                    .push(inner)
                    .push(
                        // Position near top-right of chat area
                        widget::container(menu)
                            .width(Length::Fill)
                            .padding(iced::Padding {
                                top: SPACE_8,
                                right: SPACE_16,
                                bottom: 0.0,
                                left: 0.0,
                            })
                            .align_x(iced::alignment::Horizontal::Right)
                            .align_y(iced::alignment::Vertical::Top),
                    )
                    .width(Length::Fill)
                    .height(Length::Fill)
                    .into()
            } else {
                // ── Emoji picker overlay ──────────────────────────
                if self.show_emoji_picker {
                    use iced::widget::Stack;
                    let picker = self.view_emoji_picker();
                    Stack::new()
                        .push(inner)
                        .push(
                            widget::container(picker)
                                .width(Length::Fill)
                                .padding(iced::Padding {
                                    top: 0.0,
                                    right: SPACE_16,
                                    bottom: 48.0,
                                    left: 0.0,
                                })
                                .align_x(iced::alignment::Horizontal::Right)
                                .align_y(iced::alignment::Vertical::Bottom),
                        )
                        .width(Length::Fill)
                        .height(Length::Fill)
                        .into()
                } else if self.show_gif_picker {
                    // ── GIF picker overlay ──────────────────────────
                    use iced::widget::Stack;
                    let picker = self.view_gif_picker();
                    Stack::new()
                        .push(inner)
                        .push(
                            widget::container(picker)
                                .width(Length::Fill)
                                .padding(iced::Padding {
                                    top: 0.0,
                                    right: SPACE_16,
                                    bottom: 48.0,
                                    left: 0.0,
                                })
                                .align_x(iced::alignment::Horizontal::Right)
                                .align_y(iced::alignment::Vertical::Bottom),
                        )
                        .width(Length::Fill)
                        .height(Length::Fill)
                        .into()
                } else {
                    inner.into()
                }
            }
        }
    }

    // ── Chat screen view ─────────────────────────────────────────────

    /// Render the right-click context menu overlay.
    fn view_context_menu(
        &self,
        idx: usize,
        kind: ContextMenuKind,
    ) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, text};

        let theme = self.theme();
        let close_btn = button(Icon::Close.build().size(IconSize::Xs).build())
            .on_press(AppMessage::CloseContextMenu)
            .padding([SPACE_2, SPACE_6])
            .style(|_t, _s| iced::widget::button::Style::default());

        let mut col = column![].spacing(0).width(180.0);

        match kind {
            ContextMenuKind::Text => {
                let copy_btn = button(
                    crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Copy Text"),
                )
                .on_press(AppMessage::ContextCopyText(idx))
                .padding([SPACE_4, SPACE_8])
                .style(|_t, _s| iced::widget::button::Style::default());
                col = col.push(
                    container(copy_btn)
                        .padding(SPACE_2)
                        .width(iced::Length::Fill),
                );
            }
            ContextMenuKind::Image => {
                let copy_img = button(
                    crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Copy Image"),
                )
                .on_press(AppMessage::ContextCopyImage(idx))
                .padding([SPACE_4, SPACE_8])
                .style(|_t, _s| iced::widget::button::Style::default());
                col = col.push(
                    container(copy_img)
                        .padding(SPACE_2)
                        .width(iced::Length::Fill),
                );
            }
        }

        let header = container(iced::widget::row![
            crate::fonts::type_role_text(
                crate::fonts::TypeRole::ButtonLabel,
                match kind {
                    ContextMenuKind::Text => "Message",
                    ContextMenuKind::Image => "Image",
                },
            )
            .color(text_muted(&theme)),
            iced::widget::Space::new().width(iced::Length::Fill),
            close_btn,
        ])
        .padding([SPACE_4, SPACE_8]);

        container(column![header, col])
            .style(move |t| iced::widget::container::Style {
                background: Some(iced::Background::Color(bg_surface(t))),
                border: iced::Border {
                    color: border_muted(t),
                    width: 1.0,
                    radius: (8.0_f32).into(),
                },
                ..Default::default()
            })
            .width(200.0)
            .into()
    }

    /// Render the emoji picker panel with commonly used emojis.
    fn view_emoji_picker(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text};

        let theme = self.theme();
        const EMOJIS: &[&str] = &[
            "😀", "😂", "🤣", "😊", "😍", "🥰", "😘", "😜", "🤔", "🙄", "😢", "😭", "😤", "😡",
            "🥺", "😎", "🤩", "👍", "👎", "👏", "🙌", "💪", "🤝", "❤️", "🔥", "⭐", "🎉", "✨",
            "💯", "✅", "❌", "⚠️", "💡", "📌", "🎵", "🌈", "🍕", "☕", "🕐", "💤",
        ];

        let close_btn = button(Icon::Close.build().size(IconSize::Xs).build())
            .on_press(AppMessage::ToggleEmojiPicker)
            .padding([SPACE_2, SPACE_4])
            .style(|_t, _s| iced::widget::button::Style::default());

        let header = row![
            crate::fonts::type_role_text(crate::fonts::TypeRole::CardTitle, "Emojis")
                .color(text_muted(&theme)),
            iced::widget::Space::new().width(iced::Length::Fill),
            close_btn,
        ]
        .spacing(SPACE_4)
        .align_y(iced::Alignment::Center);

        let mut grid = column![].spacing(SPACE_2);
        for chunk in EMOJIS.chunks(8) {
            let mut r = row![].spacing(SPACE_2);
            for &emoji in chunk {
                let c = emoji.chars().next().unwrap();
                r = r.push(
                    button(text(emoji).size(20.0))
                        .on_press(AppMessage::InsertEmoji(c))
                        .padding([SPACE_2, SPACE_4])
                        .style(|_t, _s| iced::widget::button::Style::default()),
                );
            }
            grid = grid.push(r);
        }

        let scroll = crate::ui_components::gutter_scrollable(grid).height(iced::Length::Fixed(160.0));

        container(column![header, scroll].spacing(SPACE_4).padding(SPACE_8))
            .style(move |t| iced::widget::container::Style {
                background: Some(iced::Background::Color(bg_surface(t))),
                border: iced::Border {
                    color: border_muted(t),
                    width: 1.0,
                    radius: (8.0_f32).into(),
                },
                ..Default::default()
            })
            .width(280.0)
            .into()
    }

    /// Render the GIF picker panel with common GIF URLs and search/custom input.
    fn view_gif_picker(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text, text_input};

        let theme = self.theme();
        let close_btn = iced::widget::tooltip::Tooltip::new(
            button(Icon::Close.build().size(IconSize::Xs).build())
                .on_press(AppMessage::ToggleGifPicker)
                .padding([SPACE_2, SPACE_4])
                .style(|_t, _s| iced::widget::button::Style::default()),
            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Close"),
            iced::widget::tooltip::Position::Bottom,
        );

        let header = row![
            crate::fonts::type_role_text(crate::fonts::TypeRole::CardTitle, "GIF Search")
                .color(text_muted(&theme)),
            iced::widget::Space::new().width(iced::Length::Fill),
            close_btn,
        ]
        .spacing(SPACE_4)
        .align_y(iced::Alignment::Center);

        // Search input
        let search_input = text_input("Search GIFs…", &self.gif_search_text)
            .on_input(AppMessage::GifSearchChanged)
            .on_submit(AppMessage::GifSearchSubmit)
            .size(crate::fonts::TypeRole::Body.size_px())
            .font(crate::fonts::TypeRole::Body.font())
            .padding([SPACE_4, SPACE_6]);

        let search_btn =
            button(crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Search"))
                .on_press_maybe(if !self.gif_search_text.is_empty() {
                    Some(AppMessage::GifSearchSubmit)
                } else {
                    None
                })
                .padding([SPACE_4, SPACE_8]);

        let search_row = row![search_input, search_btn]
            .spacing(SPACE_4)
            .align_y(iced::Alignment::Center);

        // Results grid with image thumbnails
        let mut results_col = column![].spacing(SPACE_4);
        if self.gif_not_configured {
            results_col = results_col.push(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SupportingText,
                    "KLIPY is not configured — set the KLIPY_API_KEY environment variable to enable external GIF search",
                )
                .color(text_muted(&theme)),
            );
        } else if self.gif_results.is_empty() {
            results_col = results_col.push(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SupportingText,
                    "Type a search term and press Enter or Search",
                )
                .color(text_muted(&theme)),
            );
        } else {
            // Render in rows of 2 thumbnails each
            for chunk in self.gif_results.chunks(2) {
                let mut row_widgets = row![].spacing(SPACE_4);
                for gif in chunk {
                    let url = gif.full_url.clone();
                    let title = if gif.title.is_empty() {
                        "GIF"
                    } else {
                        &gif.title
                    };
                    let has_preview = !gif.preview_bytes.is_empty();

                    let thumbnail: iced::Element<'_, AppMessage> = if has_preview {
                        let handle =
                            iced::widget::image::Handle::from_bytes(gif.preview_bytes.clone());
                        iced::widget::image(handle)
                            .width(iced::Length::Fixed(150.0))
                            .height(iced::Length::Fixed(100.0))
                            .into()
                    } else {
                        container(
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Metadata,
                                "...",
                            )
                            .color(text_muted(&theme)),
                        )
                        .width(150.0)
                        .height(100.0)
                        .center_x(iced::Length::Fill)
                        .center_y(iced::Length::Fill)
                        .style(move |t| iced::widget::container::Style {
                            background: Some(iced::Background::Color(bg_surface_secondary(t))),
                            ..Default::default()
                        })
                        .into()
                    };

                    let card = button(
                        column![
                            thumbnail,
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Metadata,
                                title,
                            )
                            .color(text_muted(&theme)),
                        ]
                        .spacing(SPACE_2)
                        .width(iced::Length::Fixed(150.0)),
                    )
                    .on_press(AppMessage::SendGifUrl(url))
                    .padding(SPACE_4)
                    .style(|_t, _s| iced::widget::button::Style::default());

                    row_widgets = row_widgets.push(card);
                }
                results_col = results_col.push(row_widgets);
            }
        }

        let scroll = crate::ui_components::gutter_scrollable(results_col).height(iced::Length::Fixed(300.0));

        container(
            column![header, search_row, scroll]
                .spacing(SPACE_6)
                .padding(SPACE_8),
        )
        .style(move |t| iced::widget::container::Style {
            background: Some(iced::Background::Color(bg_surface(t))),
            border: iced::Border {
                color: border_muted(t),
                width: 1.0,
                radius: (8.0_f32).into(),
            },
            ..Default::default()
        })
        .width(320.0)
        .into()
    }

    fn view_chat_header(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text};
        use iced::{Alignment, Length};

        let topic_hex = self.topic.to_string();
        let short_topic = &topic_hex[..8.min(topic_hex.len())];
        let conversation = self
            .conversation_store
            .active_iter()
            .into_iter()
            .find(|entry| entry.topic == self.topic);
        let room_name = conversation
            .map(|entry| entry.display_name())
            .unwrap_or_else(|| format!("Room {short_topic}"));
        let is_group = conversation
            .as_ref()
            .map(|entry| {
                matches!(
                    entry.kind,
                    boru_core::conversations::ConversationKind::Group
                )
            })
            .unwrap_or(false);
        let peer = conversation.and_then(|entry| PublicKey::from_str(&entry.peer_id).ok());

        // Presence: while the subscription or gossip sender is still coming
        // up we show Connecting; if no peer identity can be resolved we show
        // Unknown instead of guessing.
        let presence = if self.room_loading || self.sender.is_none() {
            PeerPresence::Connecting
        } else {
            peer.map(|key| self.peer_presence(&key))
                .unwrap_or(PeerPresence::Unknown)
        };

        // ── Shared ghost icon toolbar button ─────────────────────────
        // Consistent padding, tooltip and BUTTON_ICON (transparent, themed
        // hover) for every header action so the toolbar reads as one system.
        fn tool_btn<'a>(
            icon: iced::widget::svg::Svg<'a, iced::Theme>,
            tip: &'static str,
            msg: Option<AppMessage>,
        ) -> iced::Element<'a, AppMessage> {
            let mut b = button(icon).padding([SPACE_4, SPACE_6]).style(BUTTON_ICON);
            if let Some(m) = msg {
                b = b.on_press(m);
            }
            iced::widget::tooltip::Tooltip::new(
                b,
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, tip),
                iced::widget::tooltip::Position::Bottom,
            )
            .into()
        };

        // Group chat header: show name + member count
        // Direct chat header: show name + online/offline status + encryption cue
        let (avatar, identity) = if is_group {
            // Group avatar: initials from group name
            let initials = crate::presentation::initials(&room_name);
            let display_initials = if initials.is_empty() {
                "G".to_string()
            } else {
                initials
            };
            let theme_for_initials = self.theme();
            let is_dark = matches!(theme_for_initials, iced::Theme::Dark);
            let letter_color = crate::presentation::initials_color(&room_name, is_dark);
            let group_avatar = container(text(display_initials).size(TYPO_SM).color(letter_color))
                .width(Length::Fixed(AVATAR_SM))
                .height(Length::Fixed(AVATAR_SM))
                .center_x(Length::Fixed(AVATAR_SM))
                .center_y(Length::Fixed(AVATAR_SM))
                .style(move |t| iced::widget::container::Style {
                    background: Some(iced::Background::Color(bg_surface_secondary(
                        &theme_for_initials,
                    ))),
                    border: iced::Border {
                        radius: SPACE_8.into(),
                        ..Default::default()
                    },
                    ..Default::default()
                })
                .into();

            let member_count = self
                .room_history
                .find(&self.topic)
                .map(|r| r.member_count)
                .unwrap_or(0);
            let member_label = if member_count > 0 {
                format!(
                    "{member_count} member{}",
                    if member_count == 1 { "" } else { "s" }
                )
            } else {
                "Group".to_string()
            };

            let group_identity = column![
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::BodyEmphasised,
                    room_name.clone(),
                )
                .width(Length::Fill)
                .wrapping(iced::widget::text::Wrapping::None),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, member_label)
                    .style(move |t| iced::widget::text::Style {
                        color: Some(text_secondary(t)),
                    }),
            ]
            .spacing(SPACE_2)
            .width(Length::Fill);

            (group_avatar, group_identity)
        } else {
            let peer_avatar: iced::Element<'_, AppMessage> = peer
                .and_then(|key| self.friend_image_handles.get(&key).and_then(|h| h.clone()))
                .map(|handle| {
                    iced::widget::image(handle)
                        .content_fit(iced::ContentFit::ScaleDown)
                        .width(Length::Fixed(AVATAR_SM))
                        .height(Length::Fixed(AVATAR_SM))
                        .into()
                })
                .unwrap_or_else(|| {
                    let initials = crate::presentation::initials(&room_name);
                    let theme_for_initials = self.theme();
                    let is_dark = matches!(theme_for_initials, iced::Theme::Dark);
                    let letter_color = crate::presentation::initials_color(&room_name, is_dark);
                    container(text(initials).size(TYPO_SM).color(letter_color))
                        .width(Length::Fixed(AVATAR_SM))
                        .height(Length::Fixed(AVATAR_SM))
                        .center_x(Length::Fixed(AVATAR_SM))
                        .center_y(Length::Fixed(AVATAR_SM))
                        .style(move |t| iced::widget::container::Style {
                            background: Some(iced::Background::Color(bg_surface_secondary(
                                &theme_for_initials,
                            ))),
                            border: iced::Border {
                                radius: SPACE_8.into(),
                                ..Default::default()
                            },
                            ..Default::default()
                        })
                        .into()
                });

            let status_text = presence.label();
            let status_dot =
                icon_svg(presence.icon(), TYPO_XS).style(move |t, _| iced::widget::svg::Style {
                    color: Some(presence.color(t)),
                });

            // CHAT-03: combined "Name | peerid" header element. The peer's
            // short ID sits next to the name with a pipe separator, and the
            // whole combined element is the single copy affordance — clicking
            // it copies the FULL peer id (toast + clipboard via CopyPeerId).
            // A tooltip reveals the full value on hover.
            let name_peer_row: iced::Element<'_, AppMessage> = match peer {
                Some(key) => {
                    let full_key = key.to_string();
                    let short_key = peer_id_short_form(&full_key);
                    let combined = row![
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::BodyEmphasised,
                            room_name.clone(),
                        )
                        .wrapping(iced::widget::text::Wrapping::None),
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::TechnicalValue,
                            format!(" | {short_key}"),
                        )
                        .style(move |t| iced::widget::text::Style {
                            color: Some(text_secondary(t)),
                        }),
                    ]
                    .spacing(SPACE_2)
                    .align_y(Alignment::Center);
                    iced::widget::tooltip::Tooltip::new(
                        iced::widget::mouse_area(combined)
                            .on_press(AppMessage::CopyPeerId(key))
                            .interaction(iced::mouse::Interaction::Pointer),
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Metadata,
                            format!("Copy peer ID · {full_key}"),
                        ),
                        iced::widget::tooltip::Position::Bottom,
                    )
                    .into()
                }
                None => crate::fonts::type_role_text(
                    crate::fonts::TypeRole::BodyEmphasised,
                    room_name.clone(),
                )
                .width(Length::Fill)
                .wrapping(iced::widget::text::Wrapping::None)
                .into(),
            };

            // Security / connection cue derived from real state: iroh always
            // transports over QUIC (encrypted); the connection type mirrors the
            // details panel (direct mesh vs relay).
            let is_mesh_neighbor = peer.is_some_and(|pk| self.neighbors.contains(&pk));
            let connection_type = if is_mesh_neighbor {
                "Direct (mesh)"
            } else if presence != PeerPresence::Offline && presence != PeerPresence::Unknown {
                "Relay"
            } else {
                "Not connected"
            };
            let lock_icon = iced::widget::tooltip::Tooltip::new(
                container(icon_svg(ICON_LOCK, TYPO_XS).style(move |t, _| {
                    iced::widget::svg::Style {
                        color: Some(text_secondary(t)),
                    }
                }))
                .padding([0.0, SPACE_2]),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::Metadata,
                    format!("QUIC encrypted · {connection_type}"),
                ),
                iced::widget::tooltip::Position::Bottom,
            );

            let peer_identity = column![
                name_peer_row,
                row![
                    status_dot,
                    crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, status_text)
                        .style(move |t| iced::widget::text::Style {
                            color: Some(presence.color(t))
                        }),
                    lock_icon,
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::Metadata,
                        "End-to-end encrypted",
                    )
                    .style(move |t| {
                        iced::widget::text::Style {
                            color: Some(text_secondary(t)),
                        }
                    }),
                ]
                .spacing(SPACE_4)
                .align_y(Alignment::Center),
            ]
            .spacing(SPACE_2)
            .width(Length::Fill);

            (peer_avatar, peer_identity)
        };

        // ── Toolbar (right side) ─────────────────────────────────────
        // Ghost icon buttons for: search, delete, copy, share, overflow.
        // All actions use the shared tool_btn helper with consistent padding,
        // tooltips, and BUTTON_ICON style.
        let search = tool_btn(
            Icon::Search.build().size(IconSize::Sm).build().into(),
            "Search",
            Some(AppMessage::ToggleChatSearch),
        );

        // Delete: uses the existing ClearHistoryRequested/ConfirmClearHistory
        // confirmation flow. First press toggles a destructive "Delete?"
        // state; second press confirms and clears the conversation.
        let is_deleting = self.history_confirm_clear;
        let delete_icon = Icon::Delete
            .build()
            .size(IconSize::Sm)
            .destructive(true)
            .build();
        let delete: iced::Element<'_, AppMessage> = if is_deleting {
            let mut b = button(delete_icon).padding([SPACE_4, SPACE_6]);
            b = b.on_press(AppMessage::ConfirmClearHistory);
            iced::widget::tooltip::Tooltip::new(
                b,
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Confirm delete"),
                iced::widget::tooltip::Position::Bottom,
            )
            .into()
        } else {
            tool_btn(
                Icon::Delete.build().size(IconSize::Sm).build().into(),
                "Clear conversation",
                Some(AppMessage::ClearHistoryRequested),
            )
        };

        // Copy: peer-ID copy moved into the combined "Name | peerid" header
        // element (CHAT-03), so the toolbar copy button only remains for
        // groups, where it copies the room ticket (invite link).
        let copy: iced::Element<'_, AppMessage> = match peer {
            Some(_key) => iced::widget::Space::new().width(Length::Fixed(0.0)).into(),
            None => {
                let ticket = self.ticket_str.clone();
                if ticket.is_empty() {
                    iced::widget::Space::new().width(Length::Fixed(0.0)).into()
                } else {
                    tool_btn(
                        Icon::Copy.build().size(IconSize::Sm).build().into(),
                        "Copy invite link",
                        Some(AppMessage::CopyToClipboard(ticket)),
                    )
                }
            }
        };

        // Share: opens the shared files catalogue for direct chats.
        let share: iced::Element<'_, AppMessage> = match peer {
            Some(key) => tool_btn(
                Icon::Share.build().size(IconSize::Sm).build().into(),
                "Shared files",
                Some(AppMessage::BrowsePeerCatalogue(key)),
            ),
            None => iced::widget::Space::new().width(Length::Fixed(0.0)).into(),
        };

        // Overflow: opens the chat options popover with room info, advertise
        // toggle, delete, and settings.
        let overflow = tool_btn(
            Icon::More.build().size(IconSize::Sm).build().into(),
            "More options",
            Some(AppMessage::ToggleChatOptions),
        );

        // ── Header area (left): back button, avatar, identity ─────────
        // Identity receives Fill so it shrinks when the toolbar needs
        // space. Wrapping in a clipping container ensures long peer IDs
        // are visually truncated rather than overflowing the header bar.
        let back_btn = tool_btn(
            Icon::Back.build().size(IconSize::Md).build().into(),
            "Back to chats",
            Some(AppMessage::GoToChatList),
        );
        let header_area = row![
            back_btn,
            avatar,
            container(identity).width(Length::Fill).clip(true),
        ]
        .spacing(SPACE_4)
        .width(Length::Fill)
        .align_y(Alignment::Center);

        // ── Toolbar (right): fixed natural width, never shrinks ──────
        // Shrink ensures action buttons stay fully visible at any window
        // size. The header area absorbs the remaining space instead.
        let toolbar = row![search, delete, copy, share, overflow,]
            .spacing(SPACE_4)
            .width(Length::Shrink)
            .align_y(Alignment::Center);

        container(
            row![header_area, toolbar]
                .spacing(SPACE_8)
                .align_y(Alignment::Center),
        )
        .width(Length::Fill)
        .height(Length::Fixed(60.0))
        .padding([SPACE_6, SPACE_10])
        .style(container_header)
        .into()
    }

    /// Return the indices of conversation entries matching the live search
    /// query (case-insensitive substring over body and sender label), capped
    /// so the results panel stays cheap to render.
    fn chat_search_matches(&self) -> Vec<usize> {
        chat_search_matches_in(&self.entries, &self.chat_search_query)
    }

    /// The restrained footer/status line below the chat composer (plan UI-16).
    ///
    /// Reports the active conversation's connection route and, when connected,
    /// the peer count. The header already owns presence + encryption (direct
    /// chats) and member count (group chats), so this footer shows only the
    /// complementary route/peer state — no status text is duplicated.
    fn view_chat_footer(&self) -> iced::Element<'_, AppMessage> {
        let conversation = self
            .conversation_store
            .active_iter()
            .into_iter()
            .find(|entry| entry.topic == self.topic);
        let peer = conversation.and_then(|entry| PublicKey::from_str(&entry.peer_id).ok());
        let is_group = conversation
            .map(|entry| {
                matches!(
                    entry.kind,
                    boru_core::conversations::ConversationKind::Group
                )
            })
            .unwrap_or(false);
        let presence = peer
            .map(|key| self.peer_presence(&key))
            .unwrap_or(PeerPresence::Unknown);
        let (route_label, connected, peer_label) =
            chat_footer_status(is_group, &self.neighbors, peer, presence);
        chat_status_footer(route_label, connected, peer_label)
    }

    /// In-conversation search panel — a compact popover listing messages that
    /// match the current query. Each result copies the full message text.
    fn view_chat_search_panel(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text, text_input};
        use iced::{Alignment, Length};

        let theme = self.theme();
        let matches = self.chat_search_matches();
        let total = self.entries.len();

        let close_btn = iced::widget::tooltip::Tooltip::new(
            button(Icon::Close.build().size(IconSize::Xs).build())
                .on_press(AppMessage::ToggleChatSearch)
                .padding([SPACE_2, SPACE_4])
                .style(BUTTON_ICON),
            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Close"),
            iced::widget::tooltip::Position::Bottom,
        );

        let header = row![
            crate::fonts::type_role_text(
                crate::fonts::TypeRole::CardTitle,
                "Search in conversation",
            ),
            iced::widget::Space::new().width(Length::Fill),
            close_btn,
        ]
        .spacing(SPACE_4)
        .align_y(Alignment::Center);

        let input = text_input("Search messages…", &self.chat_search_query)
            .on_input(AppMessage::ChatSearchQueryChanged)
            .on_submit(AppMessage::ToggleChatSearch)
            .size(crate::fonts::TypeRole::Body.size_px())
            .font(crate::fonts::TypeRole::Body.font())
            .padding([SPACE_4, SPACE_6]);

        let summary = if self.chat_search_query.trim().is_empty() {
            crate::fonts::type_role_text(
                crate::fonts::TypeRole::Metadata,
                format!("{total} messages loaded"),
            )
            .color(text_muted(&theme))
        } else {
            crate::fonts::type_role_text(
                crate::fonts::TypeRole::Metadata,
                format!(
                    "{} match{}",
                    matches.len(),
                    if matches.len() == 1 { "" } else { "es" }
                ),
            )
            .color(accent_primary(&theme))
        };

        let mut results = column![].spacing(SPACE_2);
        if matches.is_empty() && !self.chat_search_query.trim().is_empty() {
            results = results.push(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SupportingText,
                    "No matching messages",
                )
                .color(text_muted(&theme)),
            );
        } else {
            for idx in &matches {
                let entry = &self.entries[*idx];
                let body = if entry.body.len() > 140 {
                    format!("{}…", &entry.body[..140])
                } else {
                    entry.body.clone()
                };
                let result_row: iced::Element<'_, AppMessage> = button(
                    column![
                        row![
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Metadata,
                                entry.label.clone(),
                            )
                            .color(text_muted(&theme)),
                            iced::widget::Space::new().width(Length::Fill),
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Metadata,
                                entry.timestamp.map(format_message_time).unwrap_or_default(),
                            )
                            .color(text_muted(&theme)),
                        ]
                        .spacing(SPACE_4),
                        crate::fonts::type_role_text(crate::fonts::TypeRole::Body, body)
                            .wrapping(iced::widget::text::Wrapping::None)
                            .color(crate::design_tokens::text(&theme)),
                    ]
                    .spacing(SPACE_2)
                    .align_x(Alignment::Start),
                )
                .on_press(AppMessage::CopyToClipboard(entry.body.clone()))
                .padding([SPACE_4, SPACE_6])
                .style(BUTTON_GHOST_BG)
                .width(Length::Fill)
                .into();
                results = results.push(result_row);
            }
        }

        let content = column![header, input, summary, crate::ui_components::gutter_scrollable(results)]
            .spacing(SPACE_6)
            .padding(SPACE_10);

        container(content)
            .style(move |t| iced::widget::container::Style {
                background: Some(iced::Background::Color(bg_surface(t))),
                border: iced::Border {
                    color: border_muted(t),
                    width: 1.0,
                    radius: SPACE_12.into(),
                },
                shadow: iced::Shadow {
                    color: iced::Color::from_rgba(0.0, 0.0, 0.0, 0.3),
                    offset: iced::Vector::new(0.0, 4.0),
                    blur_radius: 24.0,
                },
                ..Default::default()
            })
            .width(Length::Fixed(380.0))
            .max_height(460.0)
            .into()
    }

    /// Render the group member list overlay — showing avatar, display name, role, and presence.
    fn view_group_member_list(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text, Space};
        use iced::{Alignment, Length};

        // Resolve the group via conversation store -> group_id -> storage -> list_group_members.
        let group_members: Option<Vec<(String, String, bool)>> = (|| {
            let conversation = self
                .conversation_store
                .active_iter()
                .into_iter()
                .find(|e| e.topic == self.topic)?;
            if !matches!(
                conversation.kind,
                boru_core::conversations::ConversationKind::Group
            ) {
                return None;
            }
            let group_id = conversation.group_id?;
            let storage = self.storage.as_ref()?;
            let rows = storage.list_group_members(group_id.as_bytes()).ok()?;
            Some(
                rows.iter()
                    .filter(|r| r.state == "Active" || r.state == "Member" || r.state == "Owner")
                    .map(|r| {
                        let pk_opt: Option<iroh::PublicKey> = if r.public_key.len() == 32 {
                            let mut arr = [0u8; 32];
                            arr.copy_from_slice(&r.public_key);
                            iroh::PublicKey::from_bytes(&arr).ok()
                        } else {
                            None
                        };
                        let display_name = pk_opt
                            .as_ref()
                            .map(|pk| {
                                self.names.get(pk).cloned().unwrap_or_else(|| {
                                    let pk_str = pk.to_string();
                                    self.conversation_store
                                        .active_iter()
                                        .into_iter()
                                        .find_map(|e| {
                                            if e.peer_id == pk_str {
                                                Some(e.name.clone())
                                            } else {
                                                None
                                            }
                                        })
                                        .unwrap_or_else(|| {
                                            let s = pk.to_string();
                                            format!("{}..{}", &s[..6], &s[s.len() - 4..])
                                        })
                                })
                            })
                            .unwrap_or_else(|| "Unknown".to_string());
                        let role = r.role.clone();
                        let online = pk_opt.is_some_and(|k| self.neighbors.contains(&k));
                        (display_name, role, online)
                    })
                    .collect::<Vec<_>>(),
            )
        })();

        let theme = self.theme();
        let dark = matches!(theme, iced::Theme::Dark);
        let bg = bg_surface(&theme);

        let header = row![
            crate::fonts::type_role_text(crate::fonts::TypeRole::CardTitle, "Group Members"),
            Space::new().width(Length::Fill),
            iced::widget::tooltip::Tooltip::new(
                button(icon_svg(ICON_CLOSE, TYPO_SM))
                    .on_press(AppMessage::ToggleMemberList)
                    .padding([SPACE_4, SPACE_6])
                    .style(BUTTON_ICON),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Close"),
                iced::widget::tooltip::Position::Bottom,
            ),
        ]
        .spacing(SPACE_4)
        .align_y(Alignment::Center)
        .padding([SPACE_8, SPACE_10]);

        let list_body: iced::Element<'_, AppMessage> = match group_members {
            Some(members) if !members.is_empty() => {
                let member_rows: Vec<iced::Element<'_, AppMessage>> = members
                    .into_iter()
                    .map(|(name, role, online)| {
                        let initials = crate::presentation::initials(&name);
                        let display_initials = if initials.is_empty() {
                            "?".to_string()
                        } else {
                            initials
                        };
                        let letter_color = crate::presentation::initials_color(&name, dark);

                        let avatar =
                            container(text(display_initials).size(TYPO_XS).color(letter_color))
                                .width(Length::Fixed(28.0))
                                .height(Length::Fixed(28.0))
                                .center_x(Length::Fixed(28.0))
                                .center_y(Length::Fixed(28.0))
                                .style(move |t| iced::widget::container::Style {
                                    background: Some(iced::Background::Color(
                                        bg_surface_secondary(&t),
                                    )),
                                    border: iced::Border {
                                        radius: SPACE_6.into(),
                                        ..Default::default()
                                    },
                                    ..Default::default()
                                });

                        let status_dot =
                            icon_svg(if online { ICON_ONLINE } else { ICON_OFFLINE }, TYPO_XS)
                                .style(move |t, _| iced::widget::svg::Style {
                                    color: Some(if online {
                                        accent_green(&t)
                                    } else {
                                        text_muted(&t)
                                    }),
                                });

                        let role_label = if role == "Owner" { "Owner" } else { "" };

                        row![
                            avatar,
                            crate::fonts::type_role_text(crate::fonts::TypeRole::Body, name)
                                .width(Length::FillPortion(3)),
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::Metadata,
                                role_label,
                            )
                            .style(move |t| iced::widget::text::Style {
                                color: Some(text_secondary(t))
                            })
                            .width(Length::FillPortion(1)),
                            status_dot,
                        ]
                        .spacing(SPACE_6)
                        .align_y(Alignment::Center)
                        .padding([SPACE_4, SPACE_10])
                        .into()
                    })
                    .collect::<Vec<iced::Element<'_, AppMessage>>>();

                crate::ui_components::gutter_scrollable(column(member_rows).spacing(SPACE_2))
                    .height(Length::Fill)
                    .into()
            }
            _ => crate::fonts::type_role_text(
                crate::fonts::TypeRole::SupportingText,
                "No members found",
            )
            .style(move |t| iced::widget::text::Style {
                color: Some(text_secondary(t)),
            })
            .width(Length::Fill)
            .into(),
        };

        container(column![header, list_body].spacing(SPACE_4))
            .width(Length::Fixed(300.0))
            .height(Length::FillPortion(3))
            .max_height(500.0)
            .style(move |t| iced::widget::container::Style {
                background: Some(iced::Background::Color(bg)),
                border: iced::Border {
                    radius: SPACE_12.into(),
                    ..Default::default()
                },
                shadow: iced::Shadow {
                    color: iced::Color::from_rgba(0.0, 0.0, 0.0, 0.3),
                    offset: iced::Vector::new(0.0, 4.0),
                    blur_radius: 24.0,
                },
                ..Default::default()
            })
            .into()
    }

    /// Build the chat options popover — a compact card with room info,
    /// navigation, and management actions.
    fn view_chat_options_popover(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text};
        use iced::{Alignment, Length};

        let topic_hex = self.topic.to_string();
        let short_topic = if topic_hex.len() > 8 {
            format!("{}…", &topic_hex[..8])
        } else {
            topic_hex.clone()
        };

        let room_name = self
            .room_history
            .find(&self.topic)
            .map(|r| r.display_name())
            .unwrap_or_else(|| format!("Room {}", short_topic));

        let is_deleting = self.room_delete_confirm_topic == Some(self.topic);
        let delete_label = if is_deleting {
            "Delete?"
        } else {
            "Delete Chat"
        };

        let ticket_short = if self.ticket_str.len() > 12 {
            format!(
                "{}…{}",
                &self.ticket_str[..6],
                &self.ticket_str[self.ticket_str.len() - 6..]
            )
        } else if !self.ticket_str.is_empty() {
            self.ticket_str.clone()
        } else {
            "—".to_string()
        };

        let online_peers = self.peer_presence_map.len();
        let is_advertised = self.advertised_rooms.contains(&self.topic);

        let content = column![
            // ── Room name ──
            crate::fonts::type_role_text(crate::fonts::TypeRole::SectionTitle, room_name.clone()),
            // ── Back button ──
            button(crate::fonts::type_role_text(
                crate::fonts::TypeRole::ButtonLabel,
                "← Back to chats",
            ))
            .on_press(AppMessage::GoToChatList)
            .style(BUTTON_GHOST_BG)
            .padding([SPACE_6, SPACE_12])
            .width(Length::Fill),
            // ── Separator ──
            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "───")
                .color(self.color_muted()),
            // ── Room info ──
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Topic: ")
                    .color(self.color_muted()),
                crate::fonts::type_role_text(crate::fonts::TypeRole::TechnicalValue, topic_hex.clone()),
            ]
            .spacing(SPACE_4),
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Ticket: ")
                    .color(self.color_muted()),
                button(
                    crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, ticket_short.clone())
                        .color(self.color_muted())
                )
                .on_press(AppMessage::CopyToClipboard(self.ticket_str.clone()))
                .style(BUTTON_GHOST_BG)
                .padding([SPACE_2, SPACE_6]),
            ]
            .spacing(SPACE_4),
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Online: ")
                    .color(self.color_muted()),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::Metadata,
                    format!("{}", online_peers),
                ),
            ]
            .spacing(SPACE_4),
            // ── Advertise toggle ──
            button(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    if is_advertised {
                        "✓ Advertised"
                    } else {
                        "Advertise in Directory"
                    },
                )
            )
            .on_press(AppMessage::ToggleAdvertiseRoom(self.topic))
            .style(BUTTON_GHOST_BG)
            .padding([SPACE_4, SPACE_10])
            .width(Length::Fill),
            // ── Separator ──
            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "───")
                .color(self.color_muted()),
            // ── Actions ──
            button(crate::fonts::type_role_text(
                crate::fonts::TypeRole::ButtonLabel,
                delete_label,
            ))
            .on_press(if is_deleting {
                AppMessage::ConfirmDeleteRoom(self.topic)
            } else {
                AppMessage::DeleteRoomRequested(self.topic)
            })
                .style(if is_deleting {
                    |t: &iced::Theme, _s: iced::widget::button::Status| {
                        iced::widget::button::Style {
                            background: Some(iced::Background::Color(color_error(t))),
                            text_color: iced::Color::WHITE,
                            border: iced::Border {
                                radius: SPACE_6.into(),
                                ..Default::default()
                            },
                            ..Default::default()
                        }
                    }
                } else {
                    BUTTON_GHOST_BG
                })
                .padding([SPACE_6, SPACE_12])
                .width(Length::Fill),
            button(crate::fonts::type_role_text(
                crate::fonts::TypeRole::ButtonLabel,
                "Settings",
            ))
            .on_press(AppMessage::OpenSettings)
            .style(BUTTON_GHOST_BG)
            .padding([SPACE_6, SPACE_12])
            .width(Length::Fill),
        ]
        .spacing(SPACE_6)
        .align_x(Alignment::Start)
        .padding(SPACE_16)
        .max_width(360.0);

        container(content)
            .style(|t| iced::widget::container::Style {
                background: Some(iced::Background::Color(bg_surface(t))),
                border: iced::Border {
                    color: border_muted(t),
                    width: 1.0,
                    radius: SPACE_12.into(),
                },
                shadow: iced::Shadow {
                    color: iced::Color::from_rgba(0.0, 0.0, 0.0, 0.3),
                    offset: iced::Vector::new(0.0, 4.0),
                    blur_radius: 24.0,
                },
                ..Default::default()
            })
            .width(Length::Shrink)
            .into()
    }

    /// Right-side details panel — shows conversation metadata and actions.
    /// For direct conversations: contact info, connection, security, tools.
    /// For groups: group info panel with name, description, members, actions.
    fn view_details_panel(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text, Space};
        use iced::{Alignment, Length};

        let theme = self.theme().clone();

        // ── Look up current conversation entry ──
        let conversation = self.conversation_store.find(&self.topic);
        let is_direct = conversation
            .as_ref()
            .map(|entry| entry.kind == boru_core::conversations::ConversationKind::Direct)
            .unwrap_or(true);

        if is_direct {
            return self.view_details_panel_direct();
        }

        // ── Group details panel ─────────────────────────────────────────
        let display_name = conversation
            .as_ref()
            .map(|entry| entry.display_name())
            .unwrap_or_else(|| "Unknown".to_string());

        let member_count = self.neighbors.len();

        // Common badge
        let kind_badge =
            container(crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Group")
                .color(accent_primary(&theme)))
            .padding([SPACE_2, SPACE_8])
            .style(move |t| container::Style {
                background: Some(iced::Background::Color({
                    let mut c = accent_primary(t);
                    c.a = 0.12;
                    c
                })),
                border: iced::Border {
                    color: {
                        let mut c = accent_primary(t);
                        c.a = 0.25;
                        c
                    },
                    width: 1.0,
                    radius: SPACE_12.into(),
                },
                ..Default::default()
            });

        // ── Group info section ──
        let mut info_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // Display name with badge
        let dn = display_name.clone();
        info_items.push(
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::BodyEmphasised, dn),
                Space::new().width(Length::Fixed(SPACE_8)),
                kind_badge,
            ]
            .align_y(Alignment::Center)
            .into(),
        );

        // Member count
        info_items.push(
            row![
                icon_svg(ICON_ONLINE, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(text_muted(t))
                }),
                Space::new().width(Length::Fixed(SPACE_4)),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::Body,
                    format!("Members · {}", member_count),
                )
                .color(text_secondary(&theme)),
            ]
            .align_y(Alignment::Center)
            .into(),
        );

        // ── Members section ──
        let mut member_rows: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // Sort neighbors for stable order — use fmt_short for display
        let mut sorted_neighbors: Vec<PublicKey> = self.neighbors.iter().copied().collect();
        sorted_neighbors.sort_by(|a, b| a.fmt_short().to_string().cmp(&b.fmt_short().to_string()));

        for neighbor in sorted_neighbors.iter().take(12) {
            let theme = theme.clone();
            let short_name = neighbor.fmt_short().to_string();
            let display_label =
                boru_core::peer_names::resolve_peer_name(neighbor, None, None, None, None);
            let is_friend = self.peer_presence(neighbor) != PeerPresence::Offline;

            let row_element = row![
                // Avatar dot
                container(Space::new())
                    .width(Length::Fixed(8.0))
                    .height(Length::Fixed(8.0))
                    .style({
                        let theme = theme.clone();
                        move |_t| container::Style {
                            background: Some(iced::Background::Color(if is_friend {
                                accent_green(&theme)
                            } else {
                                text_muted(&theme)
                            })),
                            border: iced::Border {
                                radius: 4.0.into(),
                                ..Default::default()
                            },
                            ..Default::default()
                        }
                    }),
                Space::new().width(Length::Fixed(SPACE_8)),
                text(display_label.clone())
                    .size(crate::fonts::TypeRole::Body.size_px())
                    .font(crate::fonts::TypeRole::Body.font())
                    .width(Length::Fill),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, short_name.clone())
                    .color(text_muted(&theme)),
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill);
            member_rows.push(row_element.into());
        }

        if self.neighbors.len() > 12 {
            member_rows.push(
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::Metadata,
                    format!("+ {} more", self.neighbors.len() - 12),
                )
                .color(text_muted(&theme))
                .into(),
            );
        }

        // Invite member button
        let invite_btn = button(
            row![
                icon_svg(ICON_USER_PLUS, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(accent_primary(t))
                }),
                crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Invite member")
                    .color(accent_primary(&theme)),
            ]
            .spacing(SPACE_6)
            .align_y(Alignment::Center),
        )
        .on_press(AppMessage::ToggleInviteMenu)
        .padding([SPACE_6, SPACE_12])
        .width(Length::Fill)
        .style(BUTTON_OUTLINE);

        // ── Settings section ──
        let settings_items: Vec<iced::Element<'_, AppMessage>> = vec![
            row![
                icon_svg(ICON_NOTIFICATION, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(text_secondary(t))
                }),
                Space::new().width(Length::Fixed(SPACE_8)),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Body, "Notifications"),
                Space::new().width(Length::Fill),
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill)
            .into(),
            row![
                icon_svg(ICON_FILES, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(text_secondary(t))
                }),
                Space::new().width(Length::Fixed(SPACE_8)),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Body, "Shared files"),
                Space::new().width(Length::Fill),
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill)
            .into(),
            row![
                icon_svg(ICON_MORE, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(text_secondary(t))
                }),
                Space::new().width(Length::Fixed(SPACE_8)),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Body, "Group information"),
                Space::new().width(Length::Fill),
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill)
            .into(),
        ];

        // ── Leave Group button (owner view would additionally show Edit group, Manage members) ──
        let leave_btn = button(crate::fonts::type_role_text(
            crate::fonts::TypeRole::ButtonLabel,
            "Leave Group",
        ))
        .padding([SPACE_6, SPACE_12])
        .width(Length::Fill)
        .style(BUTTON_DANGER);

        // ── Assemble the panel ──
        let panel_body = column![
            // Heading
            crate::fonts::type_role_text(crate::fonts::TypeRole::CardTitle, "Details"),
            Space::new().height(Length::Fixed(SPACE_8)),
            // Info section
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Group info")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(info_items).spacing(SPACE_4),
            divider(&theme),
            // Members section
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Members")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(member_rows).spacing(SPACE_8),
            Space::new().height(Length::Fixed(SPACE_4)),
            invite_btn,
            divider(&theme),
            // Settings section
            column(settings_items).spacing(SPACE_10),
            divider(&theme),
            // Leave
            leave_btn,
            Space::new().height(Length::Fill),
        ]
        .spacing(SPACE_4);

        container(crate::ui_components::gutter_scrollable(panel_body))
            .width(Length::Fill)
            .height(Length::Fill)
            .padding([SPACE_8, SPACE_8])
            .style(container_surface)
            .into()
    }

    /// Direct-chat details panel — contact info, connection, security, tools.
    fn view_details_panel_direct(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text, Space};
        use iced::{Alignment, Length};

        let theme = self.theme();

        // ── Look up current conversation entry ──
        let conversation = self.conversation_store.find(&self.topic);
        let peer = conversation
            .as_ref()
            .and_then(|entry| entry.peer_id.parse::<PublicKey>().ok());
        let presence = peer
            .map(|key| self.peer_presence(&key))
            .unwrap_or(PeerPresence::Offline);
        let is_online = presence != PeerPresence::Offline;
        let display_name = conversation
            .as_ref()
            .map(|entry| entry.display_name())
            .unwrap_or_else(|| "Unknown".to_string());
        let last_seen = conversation
            .as_ref()
            .map(|entry| {
                if presence == PeerPresence::Online {
                    "Online now".to_string()
                } else if presence == PeerPresence::Away {
                    "Away".to_string()
                } else if entry.last_seen_at_unix_ms > 0 {
                    format_last_seen(Some(entry.last_seen_at_unix_ms))
                } else {
                    String::new()
                }
            })
            .unwrap_or_default();

        // ── Determine connection type for this peer ──
        let is_mesh_neighbor = peer.is_some_and(|pk| self.neighbors.contains(&pk));
        let connection_type = if is_mesh_neighbor {
            "Direct (mesh)"
        } else if is_online {
            "Relay"
        } else {
            "Not connected"
        };
        let connection_label = if is_online {
            "Connected"
        } else {
            "Disconnected"
        };

        // ── Section: Contact ──
        let mut contact_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // Presence row: status dot + label
        contact_items.push(
            row![
                icon_svg(presence.icon(), TYPO_SM,).style(move |t, _| iced::widget::svg::Style {
                    color: Some(presence.color(t))
                }),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Body, presence.label())
                    .style(move |t| iced::widget::text::Style {
                        color: Some(presence.color(t))
                    }),
            ]
            .spacing(SPACE_6)
            .align_y(Alignment::Center)
            .into(),
        );

        // Kind badge
        let kind_badge = container(
            crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Direct")
                .color(accent_primary(&theme)),
        )
            .padding([SPACE_2, SPACE_8])
            .style(move |t| container::Style {
                background: Some(iced::Background::Color({
                    let mut c = accent_primary(t);
                    c.a = 0.12;
                    c
                })),
                border: iced::Border {
                    color: {
                        let mut c = accent_primary(t);
                        c.a = 0.25;
                        c
                    },
                    width: 1.0,
                    radius: SPACE_12.into(),
                },
                ..Default::default()
            });
        // Display name with badge
        let dn = display_name.clone();
        contact_items.push(
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::BodyEmphasised, dn),
                Space::new().width(Length::Fixed(SPACE_8)),
                kind_badge,
            ]
            .align_y(Alignment::Center)
            .into(),
        );

        if !last_seen.is_empty() {
            contact_items.push(info_row("Last seen".to_string(), last_seen, &theme).into());
        }

        // Peer ID with copy button
        if let Some(pk) = peer {
            let full_id = pk.to_string();
            let fid = full_id.clone();
            let copy_btn = button(
                crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Copy")
                    .color(text_muted(&theme)),
            )
            .on_press(AppMessage::CopyToClipboard(fid))
            .padding([SPACE_2, SPACE_4])
            .style(BUTTON_GHOST_BG);

            let truncated = if full_id.len() > 32 {
                format!("{}…", &full_id[..32])
            } else {
                full_id.clone()
            };
            let peer_id_row = row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Peer ID")
                    .color(text_secondary(&theme)),
                Space::new().width(Length::Fill),
                crate::fonts::type_role_text(crate::fonts::TypeRole::TechnicalValue, truncated)
                    .color(crate::design_tokens::text(&theme)),
                copy_btn,
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill);
            contact_items.push(peer_id_row.into());
        }

        // First-seen / created date
        if let Some(entry) = conversation.as_ref() {
            if entry.created_at_unix_ms > 0 {
                let created = crate::presentation::relative_time(entry.created_at_unix_ms);
                contact_items.push(info_row("First seen".to_string(), created, &theme).into());
            }
        }

        // ── Section: Connection ──
        let mut conn_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // Connection state indicator
        let conn_state_color = if is_online {
            accent_green(&theme)
        } else {
            text_muted(&theme)
        };
        let conn_state_dot = icon_svg(if is_online { ICON_ONLINE } else { ICON_OFFLINE }, TYPO_SM)
            .style(move |_t, _| iced::widget::svg::Style {
                color: Some(conn_state_color),
            });
        let conn_state_row = row![
            conn_state_dot,
            crate::fonts::type_role_text(crate::fonts::TypeRole::Body, connection_label)
                .style(move |t| iced::widget::text::Style {
                    color: Some(if is_online {
                        accent_green(t)
                    } else {
                        text_muted(t)
                    }),
                }),
        ]
        .spacing(SPACE_6)
        .align_y(Alignment::Center);
        conn_items.push(conn_state_row.into());

        conn_items.push(
            info_row(
                "Connection".to_string(),
                connection_type.to_string(),
                &theme,
            )
            .into(),
        );

        // Relay mode
        let relay_label = fmt_relay_mode(&self.relay_mode);
        conn_items.push(info_row("Relay".to_string(), relay_label, &theme).into());

        // Latency
        if let Some(pk) = peer {
            if let Some(latency) = self.peer_latencies.get(&pk) {
                let ms = latency.as_millis();
                conn_items.push(info_row("Latency".to_string(), format!("{ms} ms"), &theme).into());
            }
        }

        // ── Section: Security ──
        let mut security_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();
        security_items.push(
            info_row(
                "Encryption".to_string(),
                "QUIC (encrypted)".to_string(),
                &theme,
            )
            .into(),
        );

        if let Some(pk) = peer {
            let fingerprint = pk.fmt_short().to_string();
            let full_key = pk.to_string();
            let fpr = fingerprint.clone();
            let copy_btn = button(
                crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Copy")
                    .color(text_muted(&theme)),
            )
            .on_press(AppMessage::CopyToClipboard(full_key.clone()))
            .padding([SPACE_2, SPACE_4])
            .style(BUTTON_GHOST_BG);

            let key_row = row![
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::SupportingText,
                    "Key fingerprint",
                )
                .color(text_secondary(&theme)),
                Space::new().width(Length::Fill),
                crate::fonts::type_role_text(crate::fonts::TypeRole::TechnicalValue, fpr)
                    .color(crate::design_tokens::text(&theme)),
                copy_btn,
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill);
            security_items.push(key_row.into());
        }

        // ── Section: Tools ──
        let mut tool_btns: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        if let Some(pk) = peer {
            let shared_files_btn = button(
                row![
                    icon_svg(ICON_FILES, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                        color: Some(accent_primary(t))
                    }),
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::ButtonLabel,
                        "Shared files",
                    )
                    .color(accent_primary(&theme)),
                ]
                .spacing(SPACE_6)
                .align_y(Alignment::Center),
            )
            .on_press(AppMessage::BrowsePeerCatalogue(pk))
            .padding([SPACE_6, SPACE_12])
            .width(Length::Fill)
            .style(BUTTON_OUTLINE);
            tool_btns.push(shared_files_btn.into());
        }

        let connection_btn = button(
            row![
                icon_svg(ICON_ACTIVITY, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(accent_primary(t))
                }),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Connection details",
                )
                .color(accent_primary(&theme)),
            ]
            .spacing(SPACE_6)
            .align_y(Alignment::Center),
        )
        .on_press(AppMessage::OpenConnectionDetails)
        .padding([SPACE_6, SPACE_12])
        .width(Length::Fill)
        .style(BUTTON_OUTLINE);
        tool_btns.push(connection_btn.into());

        // Only show if we have a valid peer key
        if let Some(pk) = peer {
            let tunnel_btn = button(
                row![
                    icon_svg(ICON_ACTIVITY, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                        color: Some(accent_primary(t))
                    }),
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::ButtonLabel,
                        "Create Tunnel",
                    )
                    .color(accent_primary(&theme)),
                ]
                .spacing(SPACE_6)
                .align_y(Alignment::Center),
            )
            .on_press(AppMessage::CreateTunnel(pk))
            .padding([SPACE_6, SPACE_12])
            .width(Length::Fill)
            .style(BUTTON_OUTLINE);
            tool_btns.push(tunnel_btn.into());
        }

        // ── Assemble the panel ──
        let panel_body = column![
            crate::fonts::type_role_text(crate::fonts::TypeRole::CardTitle, "Details"),
            Space::new().height(Length::Fixed(SPACE_8)),
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Contact")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(contact_items).spacing(SPACE_4),
            divider(&theme),
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Connection")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(conn_items).spacing(SPACE_4),
            divider(&theme),
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Security")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(security_items).spacing(SPACE_4),
            divider(&theme),
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Tools")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(tool_btns).spacing(SPACE_4),
            Space::new().height(Length::Fill),
        ]
        .spacing(SPACE_4);

        container(crate::ui_components::gutter_scrollable(panel_body))
            .width(Length::Fill)
            .height(Length::Fill)
            .padding([SPACE_8, SPACE_8])
            .style(container_surface)
            .into()
    }

    /// Right-side group info panel — shown when the active conversation is a group.
    fn view_group_info_panel(&self) -> iced::Element<'_, AppMessage> {
        use iced::widget::{button, column, container, row, text, Space};
        use iced::{Alignment, Length};

        let theme = self.theme();
        let conversation = self.conversation_store.find(&self.topic);
        let display_name = conversation
            .as_ref()
            .map(|entry| entry.display_name())
            .unwrap_or_else(|| "Group".to_string());
        let room_entry = self.room_history.find(&self.topic);
        let description = room_entry
            .and_then(|r| {
                // Use room metadata description from room_history or room_docs
                // For now derive it (stored in room history through the group creation path)
                None::<String>
            })
            .unwrap_or_default();

        let member_count = room_entry.map(|r| r.member_count).unwrap_or(0);
        let is_owner = room_entry.map(|r| r.is_owner).unwrap_or(true);

        // ── Section: Group Info ──
        let mut info_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // Group name
        info_items.push(
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::BodyEmphasised, display_name.clone()),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Group")
                    .color(accent_primary(&theme)),
            ]
            .spacing(SPACE_8)
            .align_y(Alignment::Center)
            .into(),
        );

        // Member count
        let member_label = if member_count > 0 {
            format!(
                "{} member{}",
                member_count,
                if member_count == 1 { "" } else { "s" }
            )
        } else {
            "Group".to_string()
        };
        info_items.push(info_row("Members".to_string(), member_label, &theme).into());

        if is_owner {
            info_items.push(info_row("Role".to_string(), "Owner".to_string(), &theme).into());
        }

        // ── Section: Members ──
        let mut member_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // List the local user
        let local_label = format!("{} (you)", self.local_label.clone());
        member_items.push(
            row![
                crate::fonts::type_role_text(crate::fonts::TypeRole::Body, local_label),
                Space::new().width(Length::Fill),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::Metadata,
                    if is_owner { "Owner" } else { "Member" },
                )
                .color(text_secondary(&theme)),
            ]
            .spacing(SPACE_4)
            .align_y(Alignment::Center)
            .width(Length::Fill)
            .into(),
        );

        // List friends who are in the group (from selected_members during creation)
        // For now show a minimal members list — full roster requires RosterDoc handle
        member_items.push(
            row![crate::fonts::type_role_text(
                crate::fonts::TypeRole::Metadata,
                format!("{} online", self.neighbors.len()),
            )
            .color(text_muted(&theme)),]
            .into(),
        );

        // ── Section: Advanced ──
        let topic_hex = self.topic.to_string();
        let short_topic = if topic_hex.len() > 16 {
            format!("{}…", &topic_hex[..16])
        } else {
            topic_hex.clone()
        };

        let mut advanced_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();
        advanced_items.push(info_row("Group ID".to_string(), short_topic, &theme).into());

        // ── Owner-only controls ──
        let mut owner_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();
        if is_owner {
            owner_items.push(
                container(
                    crate::fonts::type_role_text(
                        crate::fonts::TypeRole::SupportingText,
                        "Owner Controls",
                    )
                    .color(text_secondary(&theme)),
                )
                .padding([SPACE_4, 0.0])
                .into(),
            );
        }

        // ── Actions ──
        let mut action_items: Vec<iced::Element<'_, AppMessage>> = Vec::new();

        // Invite member button (owner only)
        let invite_btn = button(
            row![
                icon_svg(ICON_PLUS, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(accent_primary(t))
                }),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Invite Member",
                )
                .color(accent_primary(&theme)),
            ]
            .spacing(SPACE_6)
            .align_y(Alignment::Center),
        )
        .on_press(AppMessage::ShowInviteMemberDialog)
        .padding([SPACE_6, SPACE_12])
        .width(Length::Fill)
        .style(BUTTON_OUTLINE);
        action_items.push(invite_btn.into());

        // Leave group button (wired but actual leave logic in Phase 16)
        let leave_btn = button(
            row![
                icon_svg(ICON_CLOSE, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(color_error(t))
                }),
                crate::fonts::type_role_text(crate::fonts::TypeRole::ButtonLabel, "Leave Group")
                    .color(color_error(&theme)),
            ]
            .spacing(SPACE_6)
            .align_y(Alignment::Center),
        )
        .padding([SPACE_6, SPACE_12])
        .width(Length::Fill)
        .style(move |t: &iced::Theme, _s| iced::widget::button::Style {
            border: iced::Border {
                color: {
                    let mut c = color_error(t);
                    c.a = 0.3;
                    c
                },
                width: 1.0,
                radius: SPACE_6.into(),
            },
            ..iced::widget::button::Style::default()
        });
        action_items.push(leave_btn.into());

        // Connection details button
        let connection_btn = button(
            row![
                icon_svg(ICON_ACTIVITY, TYPO_SM).style(|t, _| iced::widget::svg::Style {
                    color: Some(accent_primary(t))
                }),
                crate::fonts::type_role_text(
                    crate::fonts::TypeRole::ButtonLabel,
                    "Connection details",
                )
                .color(accent_primary(&theme)),
            ]
            .spacing(SPACE_6)
            .align_y(Alignment::Center),
        )
        .on_press(AppMessage::OpenConnectionDetails)
        .padding([SPACE_6, SPACE_12])
        .width(Length::Fill)
        .style(BUTTON_OUTLINE);
        action_items.push(connection_btn.into());

        // ── Assemble the panel ──
        let panel_body = column![
            // Heading
            crate::fonts::type_role_text(crate::fonts::TypeRole::CardTitle, "Group Info"),
            Space::new().height(Length::Fixed(SPACE_8)),
            // Group Info section
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "About")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(info_items).spacing(SPACE_4),
            divider(&theme),
            // Members section
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Members")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(member_items).spacing(SPACE_4),
            divider(&theme),
            // Advanced section
            crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Advanced")
                .color(text_secondary(&theme)),
            Space::new().height(Length::Fixed(SPACE_2)),
            column(advanced_items).spacing(SPACE_4),
        ]
        .spacing(SPACE_4);

        // Build the full panel with owner controls and actions at the bottom
        let mut full_panel = column![panel_body].spacing(0);

        if !owner_items.is_empty() {
            full_panel = full_panel.push(divider(&theme));
            full_panel = full_panel.push(column(owner_items).spacing(SPACE_4));
        }

        full_panel = full_panel.push(divider(&theme));
        full_panel = full_panel.push(
            column![
                crate::fonts::type_role_text(crate::fonts::TypeRole::SupportingText, "Actions")
                    .color(text_secondary(&theme)),
                Space::new().height(Length::Fixed(SPACE_2)),
                column(action_items).spacing(SPACE_4),
            ]
            .spacing(SPACE_4),
        );

        full_panel = full_panel.push(Space::new().height(Length::Fill));

        container(crate::ui_components::gutter_scrollable(full_panel))
            .width(Length::Fill)
            .height(Length::Fill)
            .padding([SPACE_8, SPACE_8])
            .style(container_surface)
            .into()
    }

    fn view_chat_log(
        &self,
        timeline_width: f32,
        viewport_height: f32,
    ) -> iced::widget::Scrollable<'_, AppMessage> {
        use iced::widget::space;
        use iced::widget::text::Wrapping;
        use iced::widget::{button, container, scrollable, text, Column, Row};
        use iced::{Alignment, Length};

        let _start = std::time::Instant::now();

        // ── Ensure layout cache is up-to-date ──
        // Uses the incrementally maintained cache so the height/cumulative passes
        // only run when entries or settings actually change, not on every frame.
        let lc = &mut *self.layout_cache.borrow_mut();
        lc.ensure(&self.entries, self.chat_text_size);

        let total_entries = self.entries.len();
        let total_image_bytes = lc.total_image_bytes;
        let image_entry_count = lc.image_entry_count;

        let theme = self.theme();

        // ── Empty state ──
        if self.entries.is_empty() {
            let col = if self.sender.is_none() {
                // Still connecting — the subscription completed but the
                // gossip sender isn't ready. Show an inline spinner.
                const SPINNER_FRAMES: [&str; 10] =
                    ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
                let spinner = SPINNER_FRAMES[self.connecting_spinner_frame % SPINNER_FRAMES.len()];
                Column::new().push(
                    container(
                        Column::new()
                            .push(text(spinner).size(28.0).color(accent_primary(&theme)))
                            .push(
                                crate::fonts::type_role_text(
                                    crate::fonts::TypeRole::Body,
                                    "Connecting…",
                                )
                                .color(self.color_muted()),
                            )
                            .spacing(SPACE_8)
                            .align_x(iced::Alignment::Center),
                    )
                    .padding([0.0, SPACE_8])
                    .width(Length::Fill)
                    .center_x(Length::Fill),
                )
            } else {
                Column::new().push(
                    container(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Body,
                            "No messages yet.",
                        )
                        .color(self.color_muted()),
                    )
                    .padding([0.0, SPACE_8])
                    .width(Length::Fill),
                )
            };
            self.total_content_height.set(0.0);
            // Empty-state render — record perf snapshot
            self.perf.replace(PerfMetrics {
                last_render_time_ns: _start.elapsed().as_nanos() as u64,
                window_size: 0,
                total_entries,
                total_image_bytes,
                image_entry_count,
            });
            return crate::ui_components::gutter_scrollable(col)
                .id(CHAT_LOG)
                .anchor_bottom()
                .width(iced::Length::Fill)
                .height(iced::Length::Fill)
                .on_scroll(|v: scrollable::Viewport| {
                    AppMessage::Scrolled(v.absolute_offset().y, v.bounds().height)
                });
        }

        // ── Use cached layout data for window computation (O(log n)) ──
        let total_height = lc.total_height;
        self.total_content_height.set(total_height);

        // Effective bubble width cap: 560 px or 68 % of the timeline width,
        // whichever is smaller (plan §4).  Supplied by the responsive wrapper
        // in `view_chat_panel` so bubbles never exceed the conversation
        // column and long content wraps instead of overflowing.
        let bubble_max_w = crate::presentation::chat_bubble_max_width(timeline_width);

        let (first_idx, last_idx, top_space_h, bottom_h) =
            lc.window(self.scroll_offset, viewport_height);

        // Bottom-align a short timeline. The scrollable keeps its Fill height
        // (so the timeline is always the sole expanding region between the
        // fixed header and the pinned composer); when the message content is
        // shorter than the viewport, a leading spacer pushes the content to
        // the bottom so it hugs the composer. Whitespace then sits above the
        // messages (balanced, chat convention) instead of leaving a giant dead
        // area below them. When content overflows the viewport the spacer is
        // zero and the anchored-to-bottom scrolling takes over unchanged.
        //
        // The cache's `total_height` sums entry heights only; the rendered
        // column also inserts `SPACE_4` between every child (leading spacer,
        // date separators, entries, bottom spacer). Count the children we are
        // about to push inside the visible window and subtract their gap
        // overhead from the lead, so a short timeline fills the viewport
        // exactly and iced does not paint a phantom near-full-height
        // scrollbar for content that already fits.
        //
        // `viewport_height` is the measured timeline region height supplied by
        // the `responsive` wrapper in `view_chat_panel` — it cannot come from
        // `self.viewport_height`, because iced only emits `Scrolled` events
        // when content overflows (short content would leave it at 0).
        let visible_count = last_idx.saturating_sub(first_idx).saturating_add(1);
        let mut date_seps_in_window = 0usize;
        {
            let mut prev_day = if first_idx > 0 {
                self.entries[first_idx - 1]
                    .timestamp
                    .map(|ts| ts / 86400000)
            } else {
                None
            };
            for i in first_idx..=last_idx {
                if let Some(day) = self.entries[i].timestamp.map(|ts| ts / 86400000) {
                    if prev_day != Some(day) {
                        date_seps_in_window += 1;
                    }
                    prev_day = Some(day);
                }
            }
        }
        // Children in the short-content layout: lead spacer + visible entries
        // + date separators (+ top/bottom spacers only when overflowing,
        // where the lead is zero anyway). Gaps = children - 1.
        let gap_overhead = SPACE_4 * (visible_count + date_seps_in_window) as f32;
        let timeline_lead = (viewport_height - total_height - gap_overhead).max(0.0);

        // ── Build windowed content column ──
        let mut col = Column::new()
            .spacing(SPACE_4)
            .width(Length::Fill)
            .align_x(Alignment::Start);

        if timeline_lead > 0.0 {
            col = col.push(
                space::Space::new()
                    .width(Length::Fill)
                    .height(Length::Fixed(timeline_lead)),
            );
        }

        if top_space_h > 0.0 {
            col = col.push(
                space::Space::new()
                    .width(Length::Fill)
                    .height(Length::Fixed(top_space_h)),
            );
        }

        let mut prev_day: Option<i64> = if first_idx > 0 {
            self.entries[first_idx - 1]
                .timestamp
                .map(|ts| ts / 86400000)
        } else {
            None
        };

        for i in first_idx..=last_idx {
            let entry = &self.entries[i];

            // ── Date divider ──
            let entry_day = crate::presentation::day_key(entry.timestamp);
            if let Some(day) = entry_day {
                if prev_day != Some(day) {
                    let today_day = crate::presentation::day_key(Some(now_ms())).unwrap_or(day);
                    let divider_label = crate::presentation::date_divider_label(
                        entry.timestamp.unwrap_or(0),
                        today_day,
                    );
                    col = col.push(crate::ui_components::date_separator(divider_label, &theme));
                }
                prev_day = Some(day);
            }

            let previous = i.checked_sub(1).map(|index| &self.entries[index]);
            let group_continues = previous.is_some_and(|previous| {
                let kind = |kind| match kind {
                    ChatKind::System => crate::presentation::MessageKind::System,
                    ChatKind::Local => crate::presentation::MessageKind::Local,
                    ChatKind::Remote => crate::presentation::MessageKind::Remote,
                };
                let previous_sender = previous.sender_key.map(|key| key.to_string());
                let current_sender = entry.sender_key.map(|key| key.to_string());
                crate::presentation::continues_message_group(
                    kind(previous.kind),
                    kind(entry.kind),
                    previous_sender.as_deref(),
                    current_sender.as_deref(),
                    previous.timestamp,
                    entry.timestamp,
                )
            });

            // Consecutive plain system notices (no download attachment — those
            // render as attachment cards, not chips) form a tight visual group:
            // their chip-to-chip gap is smaller than the spacing around user
            // message bubbles. Grouping is purely visual; entries are never
            // reordered or filtered based on display type.
            let system_group_continues = {
                let is_plain_system = |entry: &ChatEntry| {
                    matches!(entry.kind, ChatKind::System) && entry.download.is_none()
                };
                is_plain_system(entry) && previous.is_some_and(is_plain_system)
            };

            // Whether the NEXT entry continues this same visual group.
            // Used to show delivery state only on the last message of a group.
            let next_continues = i + 1 < total_entries && {
                let next = &self.entries[i + 1];
                let kind = |kind| match kind {
                    ChatKind::System => crate::presentation::MessageKind::System,
                    ChatKind::Local => crate::presentation::MessageKind::Local,
                    ChatKind::Remote => crate::presentation::MessageKind::Remote,
                };
                let current_sender = entry.sender_key.map(|key| key.to_string());
                let next_sender = next.sender_key.map(|key| key.to_string());
                crate::presentation::continues_message_group(
                    kind(entry.kind),
                    kind(next.kind),
                    current_sender.as_deref(),
                    next_sender.as_deref(),
                    entry.timestamp,
                    next.timestamp,
                )
            };

            // ── Local / Remote / System-with-download messages ──
            let label_color = match entry.kind {
                ChatKind::Local => text_local_label(&theme),
                ChatKind::Remote => text_remote_label(&theme),
                ChatKind::System => text_muted(&theme),
            };
            let body_color = match entry.kind {
                ChatKind::Local => text_local_body(&theme),
                ChatKind::Remote => text_remote_body(&theme),
                ChatKind::System => text_muted(&theme),
            };

            let label_text = entry.label_text.as_deref().unwrap_or(&entry.label);
            let is_friend_online = entry
                .sender_key
                .map_or(false, |k| self.peer_presence(&k) != PeerPresence::Offline);
            let label_el: iced::Element<'_, AppMessage> =
                if matches!(entry.kind, ChatKind::System) && entry.download.is_none() {
                    // System notices have no label — just the centred text
                    space::Space::new().height(0.0).into()
                } else if group_continues {
                    // No label inside a group — the inter-bubble gap is the
                    // plan's 6 px message-group gap.
                    space::Space::new().height(Length::Fixed(0.0)).into()
                } else if matches!(entry.kind, ChatKind::Remote) {
                    if let Some(sender_key) = entry.sender_key {
                        let status_icon = icon_svg(
                            if is_friend_online {
                                ICON_ONLINE
                            } else {
                                ICON_OFFLINE
                            },
                            TYPO_XXS,
                        )
                        .style(move |t, _| iced::widget::svg::Style {
                            color: Some(if is_friend_online {
                                accent_green(t)
                            } else {
                                Self::muted_color(false)
                            }),
                        });
                        button(
                            Row::new()
                                .push(status_icon)
                                .push(
                                    text(label_text)
                                        .size(crate::fonts::TypeRole::ChatSender.size_px())
                                        .font(crate::fonts::TypeRole::ChatSender.font())
                                        .color(label_color),
                                )
                                .spacing(SPACE_4)
                                .align_y(Alignment::Center),
                        )
                        .on_press(AppMessage::OpenPeerProfile(sender_key))
                        .padding(0)
                        .style(|_t, _s| iced::widget::button::Style::default())
                        .into()
                    } else {
                        text(label_text)
                            .size(crate::fonts::TypeRole::ChatSender.size_px())
                            .font(crate::fonts::TypeRole::ChatSender.font())
                            .color(label_color)
                            .into()
                    }
                } else {
                    // Local messages: make label clickable for retry when Failed
                    if matches!(entry.kind, ChatKind::Local)
                        && entry.delivery_state == DeliveryState::Failed
                    {
                        let event_id = entry.event_id;
                        button(
                            text(label_text)
                                .size(crate::fonts::TypeRole::ChatSender.size_px())
                                .font(crate::fonts::TypeRole::ChatSender.font())
                                .color(label_color),
                        )
                        .on_press(AppMessage::RetryOutgoingMessage(event_id))
                        .padding(0)
                        .style(|_t, _s| iced::widget::button::Style::default())
                        .into()
                    } else {
                        text(label_text)
                            .size(crate::fonts::TypeRole::ChatSender.size_px())
                            .font(crate::fonts::TypeRole::ChatSender.font())
                            .color(label_color)
                            .into()
                    }
                };

            // ── Clickable URL-aware body ──
            let segments = entry.parsed_segments.as_deref().unwrap_or(&[]);
            let body_el: iced::Element<'_, AppMessage> = if segments.len() == 1
                && matches!(&segments[0], link_preview::TextSegment::Text(_))
            {
                // No URLs — simple text element. `WordOrGlyph` wraps at word
                // boundaries and falls back to glyph-level breaking for
                // unbreakable words (public keys, pasted tokens, very long
                // single words) so the bubble never overflows its width cap.
                text(&entry.body)
                    .size(self.chat_text_size)
                    .font(crate::fonts::TypeRole::ChatMessage.font())
                    .line_height(iced::widget::text::LineHeight::Relative(1.45))
                    .wrapping(Wrapping::WordOrGlyph)
                    .color(body_color)
                    .into()
            } else {
                // Mixed text and URLs — build a segmented row
                let mut row = Row::new().spacing(0);
                for seg in segments {
                    match seg {
                        link_preview::TextSegment::Text(t) => {
                            row = row.push(
                                text(t)
                                    .size(self.chat_text_size)
                                    .font(crate::fonts::TypeRole::ChatMessage.font())
                                    .line_height(iced::widget::text::LineHeight::Relative(1.45))
                                    .wrapping(Wrapping::WordOrGlyph)
                                    .color(body_color),
                            );
                        }
                        link_preview::TextSegment::Url(u) => {
                            let display = link_preview::truncate_url(&u, 80);
                            let url_for_click = u.clone();
                            row = row.push(
                                button(
                                    text(display)
                                        .size(self.chat_text_size)
                                        .font(crate::fonts::TypeRole::ChatMessage.font())
                                        .line_height(iced::widget::text::LineHeight::Relative(1.45))
                                        .wrapping(Wrapping::WordOrGlyph)
                                        .color(accent_primary(&theme)),
                                )
                                .on_press(AppMessage::OpenUrl(url_for_click))
                                .padding(0)
                                .style(|_t, _s| iced::widget::button::Style::default()),
                            );
                        }
                    }
                }
                // Keep URL segments clickable while allowing the row to
                // create additional lines when the bubble reaches its
                // available width.
                row.wrap().into()
            };

            let bubble =
                container(body_el)
                    .padding([SPACE_10, SPACE_16])
                    .style(move |t: &iced::Theme| {
                        let mut s = iced::widget::container::Style {
                            border: crate::design_tokens::bubble_border(
                                t,
                                entry.kind == ChatKind::Local,
                                entry.kind == ChatKind::System,
                                matches!(entry.kind, ChatKind::Local)
                                    && entry.delivery_state == DeliveryState::Failed,
                            )
                            .unwrap_or_default(),
                            ..Default::default()
                        };
                        if let Some(bg) = bubble_bg(t, entry.kind) {
                            s.background = Some(bg);
                        }
                        s
                    });

            // Wrap non-system bubbles in a button so clicking copies the
            // message body to the clipboard with a toast confirmation.
            // Also wrap in a mouse_area so right-click opens a context menu.
            let clickable_bubble: iced::Element<'_, AppMessage> =
                if !matches!(entry.kind, ChatKind::System) && !entry.body.is_empty() {
                    let idx = i;
                    iced::widget::mouse_area(
                        button(bubble)
                            .on_press(AppMessage::CopyMessage(i))
                            .padding(0)
                            .style(|_t, _s| iced::widget::button::Style::default()),
                    )
                    .on_right_press(AppMessage::RightClickText(idx))
                    .into()
                } else {
                    bubble.into()
                };

            let ts_text = entry.formatted_time.as_deref().unwrap_or("");
            let metadata = if matches!(entry.kind, ChatKind::Local) && !next_continues {
                format!(
                    "{} · {}",
                    ts_text,
                    crate::presentation::delivery_label(&entry.delivery_state)
                )
            } else {
                ts_text.to_string()
            };
            let ts_el = text(metadata)
                .size(crate::fonts::TypeRole::ChatMetadata.size_px())
                .font(crate::fonts::TypeRole::ChatMetadata.font())
                .color(text_muted(&theme));

            let mut bubble_col = Column::new()
                .spacing(SPACE_2)
                .max_width(bubble_max_w)
                .width(Length::Fill)
                // Outgoing groups hug the right edge (avatar trailing), so
                // their bubble + timestamp align right inside the reserved
                // column; incoming groups hug the left edge.
                .align_x(if matches!(entry.kind, ChatKind::Local) {
                    iced::Alignment::End
                } else {
                    iced::Alignment::Start
                });
            // Skip the body bubble for image-only entries (empty body + image present)
            if entry.body.is_empty() && entry.image_handle.is_some() {
                bubble_col = bubble_col.push(ts_el);
            } else {
                bubble_col = bubble_col.push(clickable_bubble).push(ts_el);
            }

            // ── Link preview card ──
            if let Some(ref preview) = entry.link_preview {
                let mut preview_children: Vec<iced::Element<'_, AppMessage>> = Vec::new();
                if let Some(ref title) = preview.title {
                    preview_children.push(
                        text(title)
                            .size(TYPO_SM)
                            .font(crate::fonts::TypeRole::ChatMessage.font())
                            .wrapping(Wrapping::WordOrGlyph)
                            .color(accent_primary(&theme))
                            .into(),
                    );
                }
                if let Some(ref desc) = preview.description {
                    preview_children.push(
                        text(desc)
                            .size(TYPO_XS)
                            .font(crate::fonts::TypeRole::ChatMessage.font())
                            .wrapping(Wrapping::WordOrGlyph)
                            .color(text_muted(&theme))
                            .into(),
                    );
                }
                if let Some(ref bytes) = preview.image_bytes {
                    let handle = iced::widget::image::Handle::from_bytes(bytes.clone());
                    preview_children.push(
                        iced::widget::image(handle)
                            .width(Length::Fill)
                            .height(Length::Fixed(180.0))
                            .content_fit(iced::ContentFit::Cover)
                            .into(),
                    );
                } else if let Some(ref img_url) = preview.image_url {
                    let display_url = link_preview::truncate_url(img_url, 60);
                    preview_children.push(
                        text(display_url)
                            .size(TYPO_XXS)
                            .font(crate::fonts::TypeRole::ChatMessage.font())
                            .wrapping(Wrapping::WordOrGlyph)
                            .color(text_muted(&theme))
                            .into(),
                    );
                }
                if !preview_children.is_empty() {
                    let prv_url = preview.url.clone();
                    let preview_card = button(
                        container(
                            Column::new()
                                .push(
                                    text(link_preview::truncate_url(&preview.url, 60))
                                        .size(TYPO_XXS)
                                        .font(crate::fonts::TypeRole::ChatMessage.font())
                                        .color(text_muted(&theme)),
                                )
                                .push(Column::with_children(preview_children).spacing(SPACE_2))
                                .spacing(SPACE_2),
                        )
                        .padding([SPACE_6, SPACE_8])
                        .width(Length::Fill)
                        .style(container_card),
                    )
                    .on_press(AppMessage::OpenUrl(prv_url))
                    .padding(0)
                    .style(|_t, _s| iced::widget::button::Style::default());
                    bubble_col = bubble_col.push(preview_card);
                }
            } else if entry.link_preview_loading {
                bubble_col = bubble_col.push({
                    const SP: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
                    let s = SP[self.splash_spinner_frame % SP.len()];
                    text(format!("{s} Loading preview…"))
                        .size(TYPO_XS)
                        .font(crate::fonts::TypeRole::ChatMessage.font())
                        .color(text_muted(&theme))
                });
            }

            // ── Avatar column ──
            // UI-14 rule: the sender avatar appears once per visual group, on
            // the group's FIRST bubble.  Subsequent bubbles in the same group
            // reserve the same-width slot so every bubble in the group shares
            // one edge.  The avatar sits at the leading edge for incoming
            // groups (left) and the trailing edge for outgoing groups (right).
            let avatar_el: iced::Element<'_, AppMessage> = if group_continues {
                space::Space::new()
                    .width(Length::Fixed(AVATAR_SM))
                    .height(Length::Fixed(AVATAR_SM))
                    .into()
            } else if let Some(ref handle) = entry.avatar_handle {
                iced::widget::image(handle.clone())
                    .content_fit(iced::ContentFit::ScaleDown)
                    .width(Length::Fixed(AVATAR_SM))
                    .height(Length::Fixed(AVATAR_SM))
                    .into()
            } else {
                // Coloured circle fallback with the sender's initial, so an
                // entry without a profile image never renders a bare "?".
                let name = entry.label.as_str();
                let initial = name
                    .chars()
                    .next()
                    .map(|c| c.to_uppercase().to_string())
                    .unwrap_or_else(|| "?".to_string());
                let dark = matches!(self.theme(), iced::Theme::Dark);
                let letter_color = crate::presentation::initials_color(name, dark);
                container(text(initial).size(TYPO_SM).color(letter_color))
                    .width(Length::Fixed(AVATAR_SM))
                    .height(Length::Fixed(AVATAR_SM))
                    .center_x(Length::Fixed(AVATAR_SM))
                    .center_y(Length::Fixed(AVATAR_SM))
                    .style(|t| iced::widget::container::Style {
                        background: Some(iced::Background::Color(bg_surface_secondary(t))),
                        border: iced::Border {
                            radius: (AVATAR_SM / 2.0).into(),
                            ..Default::default()
                        },
                        ..Default::default()
                    })
                    .into()
            };

            let msg_row = match entry.kind {
                ChatKind::Remote => Row::new()
                    .push(avatar_el)
                    .push(bubble_col)
                    .align_y(iced::Alignment::Center)
                    .spacing(SPACE_8),
                ChatKind::Local => Row::new()
                    .push(bubble_col)
                    .push(avatar_el)
                    .align_y(iced::Alignment::Center)
                    .spacing(SPACE_8),
                // System entries with a download attachment render the
                // download card directly (upload progress, received file).
                // Plain text system events render as small centred notices.
                ChatKind::System => {
                    let download = entry
                        .download
                        .as_ref()
                        .map(|dl| self.view_download_attachment(i, dl, timeline_width));
                    if let Some(dl_el) = download {
                        // Right padding keeps the card clear of the
                        // scrollable's overlay scrollbar (~12 px).
                        Row::new()
                            .push(dl_el)
                            .width(Length::Shrink)
                            .padding(iced::Padding::default().right(SPACE_12))
                    } else {
                        // UI-29: plain, subtle inline text for system notices.
                        // No bubble surface, no label chip, no icon slot — just
                        // the muted message, centred like the date separators,
                        // so it reads as a system annotation rather than a
                        // participant message.
                        Row::new()
                            .push(
                                container(
                                    text(&entry.body)
                                        .size(TYPO_XS)
                                        .font(crate::fonts::TypeRole::ChatMessage.font())
                                        .color(text_muted(&theme))
                                        .wrapping(Wrapping::WordOrGlyph),
                                )
                                .width(Length::Fill)
                                .center_x(Length::Fill)
                                .max_width(720.0)
                                .padding([0.0, SPACE_12]),
                            )
                            .width(Length::Fill)
                    }
                }
            }
            .width(Length::Fill);

            // CHAT-02: anchor the sender name to the same side as the message
            // body. The wrapping column defaults to align_x(Start), which
            // pinned own-message usernames to the LEFT edge while their bubble
            // hugged the right. Own messages anchor the label right (End),
            // received/system entries keep it left (Start) — the same side as
            // their bubble, regardless of message length.
            let label_align = if matches!(entry.kind, ChatKind::Local) {
                iced::Alignment::End
            } else {
                iced::Alignment::Start
            };
            col = col.push(
                Column::new()
                    .push(label_el)
                    .push(msg_row)
                    .align_x(label_align)
                    .spacing(
                        if system_group_continues {
                            // Consecutive system chips are grouped tightly: the
                            // gap between chips is smaller than the spacing
                            // around user message bubbles (normal spacing
                            // below).
                            SPACE_2
                        } else if group_continues {
                            // 6 px gap between bubbles inside one sender group
                            // (plan §4).
                            SPACE_6
                        } else if matches!(entry.kind, ChatKind::System) {
                            SPACE_4
                        } else {
                            // 18 px group-to-group gap between different sender
                            // groups (plan §4).
                            SPACE_18
                        },
                    ),
            );

            // ── Image card header (PAPIRUS-10) ────────────────────────────
            // Image messages carry the central Papirus image-type icon beside
            // the filename in the card header; the preview itself stays the
            // main visual.  Live entries drop the original filename from the
            // protocol (body is empty), so the header shows a generic "Image"
            // label; history replay restores the stored filename into `body`.
            let is_image_entry = entry.image_bytes.is_some()
                || entry.image_identifier.is_some()
                || entry.image_error.is_some()
                || entry.gif_frames.is_some();
            if is_image_entry {
                let icon_name = if !entry.body.is_empty() {
                    entry.body.clone()
                } else if let Some(id) = entry.image_identifier.as_deref() {
                    id.rsplit('/').next().unwrap_or("image").to_string()
                } else {
                    "image".to_string()
                };
                let header_label = if entry.body.is_empty() {
                    "Image".to_string()
                } else {
                    entry.body.clone()
                };
                let image_header = Row::new()
                    .push(crate::download_progress_view::file_type_icon_element_with_tooltip(
                        &icon_name,
                        None,
                        None,
                        crate::file_type_icon::FileTypeIconSize::List,
                        &theme,
                    ))
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Metadata,
                            header_label,
                        )
                        .color(text_muted(&theme)),
                    )
                    .spacing(SPACE_6)
                    .align_y(Alignment::Center);
                col = col.push(image_header);
            }

            // ── Image / animated GIF (decoded once at construction) ──
            // Display size is computed by the shared helper used by the
            // LayoutCache too, so the rendered box always matches the
            // cached height — that is what keeps the scrollbar stable as
            // images enter the window and prevents decode-driven reflow.
            let (display_w, display_h) = chat_image_display_size(entry);

            if let Some(frames) = entry.gif_frames.as_deref() {
                // Animated GIF: the iced-moving-picture Gif widget manages its
                // own state tree and advances frames via per-frame delays +
                // request_redraw_at, so each GIF animates independently at the
                // correct speed (no global 100ms tick, no PNG re-encode).
                let img = iced_moving_picture::widget::gif::Gif::new(frames)
                    .content_fit(iced::ContentFit::ScaleDown)
                    .width(Length::Fixed(display_w))
                    .height(Length::Fixed(display_h));
                // Keep the preview edge consistent.
                let framed = container(img)
                    .width(Length::Fixed(display_w))
                    .height(Length::Fixed(display_h))
                    .style(|t| iced::widget::container::Style {
                        border: iced::Border {
                            color: border_muted(t),
                            width: 1.0,
                            radius: ATTACHMENT_RADIUS.into(),
                        },
                        ..Default::default()
                    });
                let thumbnail = iced::widget::button(framed)
                    .on_press(AppMessage::OpenImageLightbox(i))
                    .padding(0)
                    .style(|_t, _s| iced::widget::button::Style::default());
                let thumb_with_right_click = iced::widget::mouse_area(thumbnail)
                    .on_right_press(AppMessage::RightClickImage(i));
                col = col.push(thumb_with_right_click);
            } else if let Some(handle) = self.image_handle_for_entry(entry) {
                let img = iced::widget::image(handle)
                    .content_fit(iced::ContentFit::ScaleDown)
                    .width(Length::Fixed(display_w))
                    .height(Length::Fixed(display_h));
                // Keep the preview edge consistent.
                let framed = container(img)
                    .width(Length::Fixed(display_w))
                    .height(Length::Fixed(display_h))
                    .style(|t| iced::widget::container::Style {
                        border: iced::Border {
                            color: border_muted(t),
                            width: 1.0,
                            radius: ATTACHMENT_RADIUS.into(),
                        },
                        ..Default::default()
                    });
                let thumbnail = iced::widget::button(framed)
                    .on_press(AppMessage::OpenImageLightbox(i))
                    .padding(0)
                    .style(|_t, _s| iced::widget::button::Style::default());
                let thumb_with_right_click = iced::widget::mouse_area(thumbnail)
                    .on_right_press(AppMessage::RightClickImage(i));
                col = col.push(thumb_with_right_click);
            } else if entry.image_error.is_some() || entry.image_identifier.is_some() {
                use iced::widget::{container, text, Column};
                let error_text = entry
                    .image_error
                    .as_deref()
                    .unwrap_or("Image preview unavailable");
                // PAPIRUS-10: the image-unavailable placeholder uses the
                // central Papirus image icon (Large) as its main visual —
                // no emoji as a file-type icon.
                let icon_name = if !entry.body.is_empty() {
                    entry.body.clone()
                } else if let Some(id) = entry.image_identifier.as_deref() {
                    id.rsplit('/').next().unwrap_or("image").to_string()
                } else {
                    "image".to_string()
                };
                let placeholder = Column::new()
                    .push(crate::download_progress_view::file_type_icon_element_with_tooltip(
                        &icon_name,
                        None,
                        None,
                        crate::file_type_icon::FileTypeIconSize::Large,
                        &theme,
                    ))
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::SupportingText,
                            "Image unavailable",
                        )
                        .color(text_system(&theme)),
                    )
                    .push(
                        crate::fonts::type_role_text(
                            crate::fonts::TypeRole::Metadata,
                            error_text,
                        )
                        .color(color_error(&theme))
                        .wrapping(Wrapping::WordOrGlyph),
                    )
                    .spacing(SPACE_2);
                // The placeholder occupies the SAME fixed box the decoded
                // image will use (display_w × display_h), so the entry
                // height never changes when the image hydrates/decodes —
                // a variable-height placeholder reflowed the windowed list
                // and made images jitter while loading.
                col = col.push(
                    container(placeholder)
                        .width(Length::Fixed(display_w))
                        .height(Length::Fixed(display_h))
                        .center_x(Length::Fill)
                        .center_y(Length::Fill)
                        .padding([SPACE_8, SPACE_10])
                        .style(container_card),
                );
            }

            // ── Reactions ──
            if let Some(ref reactions_text) = entry.reactions_text {
                let reactions_line = Row::new()
                    .push(
                        text(reactions_text)
                            .color(text_muted(&theme))
                            .size(TYPO_SM)
                            .font(crate::fonts::TypeRole::ChatMessage.font())
                            .wrapping(Wrapping::WordOrGlyph)
                            .width(Length::Fill),
                    )
                    .spacing(0)
                    .padding([0.0, SPACE_8])
                    .width(Length::Fill);
                col = col.push(reactions_line);
            }
        }

        if let Some(filename) = &self.pending_image_upload {
            const SPINNER_FRAMES: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
            let spinner = SPINNER_FRAMES[self.image_upload_spinner_frame % SPINNER_FRAMES.len()];
            col = col.push(
                container(
                    Row::new()
                        .push(text(spinner).size(TYPO_LG).color(text_muted(&theme)))
                        .push(
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::SupportingText,
                                format!("Processing {filename}…"),
                            )
                            .color(text_muted(&theme)),
                        )
                        .spacing(SPACE_8)
                        .align_y(iced::Alignment::Center),
                )
                .padding([SPACE_8, SPACE_10])
                .style(container_card),
            );
        }

        if let Some((filename, file_size)) = &self.pending_file_upload {
            const SPINNER_FRAMES: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
            let spinner = SPINNER_FRAMES[self.file_upload_spinner_frame % SPINNER_FRAMES.len()];
            let size_label = {
                let bytes = *file_size;
                const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];
                let mut value = bytes as f64;
                let mut unit_idx = 0usize;
                while value >= 1024.0 && unit_idx < UNITS.len() - 1 {
                    value /= 1024.0;
                    unit_idx += 1;
                }
                if unit_idx == 0 {
                    format!("{bytes} {} ", UNITS[unit_idx])
                } else {
                    format!("{value:.1} {} ", UNITS[unit_idx])
                }
            };
            col = col.push(
                container(
                    Row::new()
                        .push(text(spinner).size(TYPO_LG).color(text_muted(&theme)))
                        .push(
                            crate::fonts::type_role_text(
                                crate::fonts::TypeRole::SupportingText,
                                format!("Uploading {filename} ({size_label})…"),
                            )
                            .color(text_muted(&theme)),
                        )
                        .spacing(SPACE_8)
                        .align_y(iced::Alignment::Center),
                )
                .padding([SPACE_8, SPACE_10])
                .style(container_card),
            );
        }

        // Bottom spacer
        // Bottom spacer (precomputed by layout cache)
        if bottom_h > 0.0 {
            col = col.push(
                container(space::Space::new().height(Length::Fixed(bottom_h))).width(Length::Fill),
            );
        }

        // ── Record render perf metrics ──
        let window_size = if total_entries > 0 {
            last_idx.saturating_sub(first_idx) + 1
        } else {
            0
        };
        self.perf.replace(PerfMetrics {
            last_render_time_ns: _start.elapsed().as_nanos() as u64,
            window_size,
            total_entries,
            total_image_bytes,
            image_entry_count,
        });

        // Top-anchored scrollable: `scroll_offset` (mirrored from the Scrolled
        // event) is a top-relative offset, which matches the windowed layout
        // cache exactly.  When following the latest message the app snaps the
        // scrollable back to the bottom via `scroll_to_bottom_pending`; when
        // the user has scrolled up, a top anchor keeps the reading position
        // fixed while live entries append below the viewport.  The empty-state
        // scrollable above keeps `anchor_bottom` because it has no content.
        crate::ui_components::gutter_scrollable(col)
            .id(CHAT_LOG)
            .width(iced::Length::Fill)
            .height(iced::Length::Fill)
            .on_scroll(|v: scrollable::Viewport| {
                AppMessage::Scrolled(v.absolute_offset().y, v.bounds().height)
            })
    }

    fn view_composer(&self) -> iced::Element<'_, AppMessage> {
        use crate::design_tokens::{RADIUS_XL, SPACE_8};
        use iced::widget::{button, container, row, text, text_input};
        use iced::{Alignment, Length, Padding};

        let has_text = !self.composer_text.is_empty();
        // A send in flight wins over the empty-text appearance: the button
        // shows a clear "sending" state until the broadcast task completes.
        let sending = self.composer_sending;

        // ── Attach button (paperclip icon) ── leading edge, left of input
        // Tooltip label so the icon-only control is identifiable without
        // relying on the glyph alone (UI-19).
        let attach_btn: iced::Element<'_, AppMessage> =
            iced::widget::tooltip::Tooltip::new(
                button(icon_svg(ICON_PAPERCLIP, TYPO_SM))
                    .on_press(AppMessage::AttachPressed)
                    .style(BUTTON_ICON)
                    .padding([SPACE_4, SPACE_6]),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Attach a file"),
                iced::widget::tooltip::Position::Bottom,
            )
            .into();

        // ── Folder button (folder icon) ── whole-directory share (SENDME-01)
        let folder_btn: iced::Element<'_, AppMessage> =
            iced::widget::tooltip::Tooltip::new(
                button(icon_svg(ICON_FOLDER, TYPO_SM))
                    .on_press(AppMessage::AttachFolderPressed)
                    .style(BUTTON_ICON)
                    .padding([SPACE_4, SPACE_6]),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Share a folder"),
                iced::widget::tooltip::Position::Bottom,
            )
            .into();

        // ── Center: expandable message input ── transparent bg, fills space
        let input = text_input("Type a message…", &self.composer_text)
            .id(COMPOSER_INPUT)
            .on_input(AppMessage::InputChanged)
            .on_submit(AppMessage::SendPressed)
            .size(self.chat_text_size)
            .font(crate::fonts::TypeRole::ComposerText.font())
            .width(Length::Fill)
            .padding(Padding::new(SPACE_8))
            .style(
                move |t: &iced::Theme, status: iced::widget::text_input::Status| {
                    let is_focused =
                        matches!(status, iced::widget::text_input::Status::Focused { .. });
                    iced::widget::text_input::Style {
                        background: iced::Background::Color(iced::Color::TRANSPARENT),
                        border: iced::Border {
                            // UI-19: focus ring uses the shared focus token
                            // (2 px, plan §4) so keyboard focus is visible on
                            // the composer exactly like every other input.
                            color: if is_focused {
                                crate::design_tokens::color_focus(t)
                            } else {
                                iced::Color::TRANSPARENT
                            },
                            width: if is_focused {
                                crate::design_tokens::FOCUS_WIDTH
                            } else {
                                0.0
                            },
                            radius: RADIUS_XL.into(),
                        },
                        icon: iced::Color::TRANSPARENT,
                        placeholder: crate::design_tokens::text_muted(t),
                        value: crate::design_tokens::text(t),
                        selection: accent_primary(t),
                    }
                },
            );

        // ── GIF picker toggle button ── trailing actions, after input
        let gif_btn = button(crate::fonts::type_role_text(
            crate::fonts::TypeRole::ButtonLabel,
            "GIF",
        ))
            .on_press(AppMessage::ToggleGifPicker)
            .style(BUTTON_ICON)
            .padding([SPACE_4, SPACE_6]);

        // ── Emoji picker toggle button ── next to GIF
        let emoji_btn: iced::Element<'_, AppMessage> =
            iced::widget::tooltip::Tooltip::new(
                button(Icon::Smile.build().size(IconSize::Sm).build())
                    .on_press(AppMessage::ToggleEmojiPicker)
                    .style(BUTTON_ICON)
                    .padding([SPACE_4, SPACE_6]),
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Emoji"),
                iced::widget::tooltip::Position::Bottom,
            )
            .into();

        // ── Right: circular green send button ──
        //  * empty composer → muted transparent circle (disabled)
        //  * text present   → filled accent-green circle with send icon
        //  * send in flight → filled green circle with a brief spinner glyph
        // The shortcut (Enter to send) is documented in the help overlay; the
        // circular affordance matches Figure 4.
        let send_btn = button(
            if sending {
                iced::Element::from(text("…").size(TYPO_MD))
            } else {
                iced::Element::from(
                    icon_svg(ICON_SEND, 18.0)
                        .style(|_t, _s| iced::widget::svg::Style {
                            color: Some(iced::Color::WHITE),
                        }),
                )
            },
        )
        .width(Length::Fixed(SPACE_18 * 2.0))
        .height(Length::Fixed(SPACE_18 * 2.0))
        .padding(0)
        .style(move |t: &iced::Theme, status: iced::widget::button::Status| {
            if sending {
                // Sending: keep the green fill but dim it and disable press.
                let mut s = BUTTON_PRIMARY_GREEN(t, iced::widget::button::Status::Disabled);
                s.border.radius = SPACE_18.into();
                s
            } else if has_text {
                let mut s = BUTTON_PRIMARY_GREEN(t, status);
                s.border.radius = SPACE_18.into();
                s
            } else {
                // Disabled: transparent circle with a muted send icon.
                let mut s = BUTTON_MUTED(t, iced::widget::button::Status::Disabled);
                s.background = None;
                s.text_color = crate::design_tokens::text_muted(t);
                s.border.radius = SPACE_18.into();
                s
            }
        });
        let send_btn = if sending || !has_text {
            send_btn
        } else {
            send_btn.on_press(AppMessage::SendPressed)
        };
        // Tooltip label so the icon-only send control is identifiable
        // without relying on the glyph alone (UI-19). Enter also sends.
        let send_btn: iced::Element<'_, AppMessage> =
            iced::widget::tooltip::Tooltip::new(
                send_btn,
                crate::fonts::type_role_text(crate::fonts::TypeRole::Metadata, "Send (Enter)"),
                iced::widget::tooltip::Position::Bottom,
            )
            .into();

        // ── Composer row ──
        //  attach | text input (fill) | gif | emoji | send
        let composer_bar = row![attach_btn, folder_btn, input, gif_btn, emoji_btn, send_btn]
            .spacing(SPACE_6)
            .align_y(Alignment::Center)
            .padding(Padding::new(SPACE_4));

        // ── Elevated rounded composer container ──
        //  16 px radius surface with a 1 px border and a very subtle shadow
        //  (plan §4: composer elevation ~0 1 2).  While a window file is
        //  dragged over the app the border adopts the accent colour as a
        //  subtle focus treatment (file-drop routes through the same
        //  attachment pipeline).
        container(composer_bar)
            .width(Length::Fill)
            .padding(Padding::new(0.0))
            .style(move |t: &iced::Theme| iced::widget::container::Style {
                background: Some(iced::Background::Color(bg_surface_secondary(t))),
                border: iced::Border {
                    width: 1.0,
                    color: if self.composer_drag_over {
                        accent_primary(t)
                    } else {
                        border_muted(t)
                    },
                    radius: RADIUS_XL.into(),
                },
                shadow: crate::design_tokens::shadow_card(t),
                ..Default::default()
            })
            .into()
    }

